(HT.schedulerSeeds = HT.schedulerSeeds || {})["ap-precalculus"] = {"id":"ap-precalculus","title":"AP Precalculus (course framework)","courseTitle":"AP Precalculus","subject":{"id":"ap-precalculus","label":"AP Precalculus"},"source":"AP Precalculus Course and Exam Description (2026 edition)","data":{"objectiveTrees":[{"id":"content","name":"AP Precalc content","levels":["Unit","Topic","Learning objective","Essential knowledge"],"nodes":[{"id":"c-1","parentId":null,"code":"1","text":"Polynomial and Rational Functions","order":1,"origin":"template","meta":{"durationMeetings":40,"examWeighting":"30–40%"}},{"id":"c-1.1","parentId":"c-1","code":"1.1","text":"Change in Tandem","order":1,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-1.2","parentId":"c-1","code":"1.2","text":"Rates of Change","order":2,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-1.3","parentId":"c-1","code":"1.3","text":"Rates of Change in Linear and Quadratic Functions","order":3,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-1.4","parentId":"c-1","code":"1.4","text":"Polynomial Functions and Rates of Change","order":4,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-1.5","parentId":"c-1","code":"1.5","text":"Polynomial Functions and Complex Zeros","order":5,"origin":"template","meta":{"durationMeetings":4,"cedClassPeriods":"2–3"}},{"id":"c-1.6","parentId":"c-1","code":"1.6","text":"Polynomial Functions and End Behavior","order":6,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"1–2"}},{"id":"c-1.7","parentId":"c-1","code":"1.7","text":"Rational Functions and End Behavior","order":7,"origin":"template","meta":{"durationMeetings":1.5,"cedClassPeriods":"1"}},{"id":"c-1.8","parentId":"c-1","code":"1.8","text":"Rational Functions and Zeros","order":8,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"1–2"}},{"id":"c-1.9","parentId":"c-1","code":"1.9","text":"Rational Functions and Vertical Asymptotes","order":9,"origin":"template","meta":{"durationMeetings":1.5,"cedClassPeriods":"1"}},{"id":"c-1.10","parentId":"c-1","code":"1.10","text":"Rational Functions and Holes","order":10,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"1–2"}},{"id":"c-1.11","parentId":"c-1","code":"1.11","text":"Equivalent Representations of Polynomial and Rational Expressions","order":11,"origin":"template","meta":{"durationMeetings":4,"cedClassPeriods":"2–3"}},{"id":"c-1.12","parentId":"c-1","code":"1.12","text":"Transformations of Functions","order":12,"origin":"template","meta":{"durationMeetings":4,"cedClassPeriods":"2–3"}},{"id":"c-1.13","parentId":"c-1","code":"1.13","text":"Function Model Selection and Assumption Articulation","order":13,"origin":"template","meta":{"durationMeetings":4,"cedClassPeriods":"2–3"}},{"id":"c-1.14","parentId":"c-1","code":"1.14","text":"Function Model Construction and Application","order":14,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-2","parentId":null,"code":"2","text":"Exponential and Logarithmic Functions","order":2,"origin":"template","meta":{"durationMeetings":45,"examWeighting":"25–40%"}},{"id":"c-2.1","parentId":"c-2","code":"2.1","text":"Change in Arithmetic and Geometric Sequences","order":1,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-2.2","parentId":"c-2","code":"2.2","text":"Change in Linear and Exponential Functions","order":2,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-2.3","parentId":"c-2","code":"2.3","text":"Exponential Functions","order":3,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"1–2"}},{"id":"c-2.4","parentId":"c-2","code":"2.4","text":"Exponential Function Manipulation","order":4,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-2.5","parentId":"c-2","code":"2.5","text":"Exponential Function Context and Data Modeling","order":5,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-2.6","parentId":"c-2","code":"2.6","text":"Competing Function Model Validation","order":6,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-2.7","parentId":"c-2","code":"2.7","text":"Composition of Functions","order":7,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-2.8","parentId":"c-2","code":"2.8","text":"Inverse Functions","order":8,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-2.9","parentId":"c-2","code":"2.9","text":"Logarithmic Expressions","order":9,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-2.10","parentId":"c-2","code":"2.10","text":"Inverses of Exponential Functions","order":10,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"2"}},{"id":"c-2.11","parentId":"c-2","code":"2.11","text":"Logarithmic Functions","order":11,"origin":"template","meta":{"durationMeetings":2.5,"cedClassPeriods":"1–2"}},{"id":"c-2.12","parentId":"c-2","code":"2.12","text":"Logarithmic Function Manipulation","order":12,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-2.13","parentId":"c-2","code":"2.13","text":"Exponential and Logarithmic Equations and Inequalities","order":13,"origin":"template","meta":{"durationMeetings":4.5,"cedClassPeriods":"3–4"}},{"id":"c-2.14","parentId":"c-2","code":"2.14","text":"Logarithmic Function Context and Data Modeling","order":14,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-2.15","parentId":"c-2","code":"2.15","text":"Semi-log Plots","order":15,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"3"}},{"id":"c-3","parentId":null,"code":"3","text":"Trigonometric and Polar Functions","order":3,"origin":"template","meta":{"durationMeetings":50,"examWeighting":"30–35%"}},{"id":"c-3.1","parentId":"c-3","code":"3.1","text":"Periodic Phenomena","order":1,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2"}},{"id":"c-3.2","parentId":"c-3","code":"3.2","text":"Sine, Cosine, and Tangent","order":2,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.3","parentId":"c-3","code":"3.3","text":"Sine and Cosine Function Values","order":3,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.4","parentId":"c-3","code":"3.4","text":"Sine and Cosine Function Graphs","order":4,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.5","parentId":"c-3","code":"3.5","text":"Sinusoidal Functions","order":5,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.6","parentId":"c-3","code":"3.6","text":"Sinusoidal Function Transformations","order":6,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.7","parentId":"c-3","code":"3.7","text":"Sinusoidal Function Context and Data Modeling","order":7,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.8","parentId":"c-3","code":"3.8","text":"The Tangent Function","order":8,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"3"}},{"id":"c-3.9","parentId":"c-3","code":"3.9","text":"Inverse Trigonometric Functions","order":9,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"3"}},{"id":"c-3.10","parentId":"c-3","code":"3.10","text":"Trigonometric Equations and Inequalities","order":10,"origin":"template","meta":{"durationMeetings":4.5,"cedClassPeriods":"3–4"}},{"id":"c-3.11","parentId":"c-3","code":"3.11","text":"The Secant, Cosecant, and Cotangent Functions","order":11,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2"}},{"id":"c-3.12","parentId":"c-3","code":"3.12","text":"Equivalent Representations of Trigonometric Functions","order":12,"origin":"template","meta":{"durationMeetings":4.5,"cedClassPeriods":"3–4"}},{"id":"c-3.13","parentId":"c-3","code":"3.13","text":"Trigonometry and Polar Coordinates","order":13,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.14","parentId":"c-3","code":"3.14","text":"Polar Function Graphs","order":14,"origin":"template","meta":{"durationMeetings":3.5,"cedClassPeriods":"2–3"}},{"id":"c-3.15","parentId":"c-3","code":"3.15","text":"Rates of Change in Polar Functions","order":15,"origin":"template","meta":{"durationMeetings":4.5,"cedClassPeriods":"4"}},{"id":"c-4","parentId":null,"code":"4","text":"Functions Involving Parameters, Vectors, and Matrices (optional — not on the AP Exam)","order":4,"origin":"template","meta":{"durationMeetings":35,"examWeighting":"0%","optional":true}},{"id":"c-4.1","parentId":"c-4","code":"4.1","text":"Parametric Functions","order":1,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2","optional":true}},{"id":"c-4.2","parentId":"c-4","code":"4.2","text":"Parametric Functions Modeling Planar Motion","order":2,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2","optional":true}},{"id":"c-4.3","parentId":"c-4","code":"4.3","text":"Parametric Functions and Rates of Change","order":3,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2","optional":true}},{"id":"c-4.4","parentId":"c-4","code":"4.4","text":"Parametrically Defined Circles and Lines","order":4,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2","optional":true}},{"id":"c-4.5","parentId":"c-4","code":"4.5","text":"Implicitly Defined Functions","order":5,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2","optional":true}},{"id":"c-4.6","parentId":"c-4","code":"4.6","text":"Conic Sections","order":6,"origin":"template","meta":{"durationMeetings":3,"cedClassPeriods":"3","optional":true}},{"id":"c-4.7","parentId":"c-4","code":"4.7","text":"Parametrization of Implicitly Defined Functions","order":7,"origin":"template","meta":{"durationMeetings":4,"cedClassPeriods":"4","optional":true}},{"id":"c-4.8","parentId":"c-4","code":"4.8","text":"Vectors","order":8,"origin":"template","meta":{"durationMeetings":3,"cedClassPeriods":"3","optional":true}},{"id":"c-4.9","parentId":"c-4","code":"4.9","text":"Vector-Valued Functions","order":9,"origin":"template","meta":{"durationMeetings":4,"cedClassPeriods":"4","optional":true}},{"id":"c-4.10","parentId":"c-4","code":"4.10","text":"Matrices","order":10,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2","optional":true}},{"id":"c-4.11","parentId":"c-4","code":"4.11","text":"The Inverse and Determinant of a Matrix","order":11,"origin":"template","meta":{"durationMeetings":2,"cedClassPeriods":"2","optional":true}},{"id":"c-4.12","parentId":"c-4","code":"4.12","text":"Linear Transformations and Matrices","order":12,"origin":"template","meta":{"durationMeetings":1,"cedClassPeriods":"1","optional":true}},{"id":"c-4.13","parentId":"c-4","code":"4.13","text":"Matrices as Functions","order":13,"origin":"template","meta":{"durationMeetings":3,"cedClassPeriods":"3","optional":true}},{"id":"c-4.14","parentId":"c-4","code":"4.14","text":"Matrices Modeling Contexts","order":14,"origin":"template","meta":{"durationMeetings":3,"cedClassPeriods":"3","optional":true}},{"id":"c-1.1.A","parentId":"c-1.1","code":"1.1.A","text":"Describe how the input and output values of a function vary together by comparing function values.","order":1,"origin":"template"},{"id":"c-1.1.A.1","parentId":"c-1.1.A","code":"1.1.A.1","text":"A function is a mathematical relation that maps a set of input values to a set of output values such that each input value is mapped to exactly one output value. The set of input values is called the domain of the function, and the set of output values is called the range of the function. The variable representing input values is called the independent variable, and the variable representing output values is called the dependent variable. Two functions, f and g, are equal if they have the same domain, and for every input value a in that same domain, both functions yield the same output value (f(a) = g(a)).","order":1,"origin":"template"},{"id":"c-1.1.A.2","parentId":"c-1.1.A","code":"1.1.A.2","text":"The input and output values of a function vary in tandem according to the function rule, which can be expressed graphically, numerically, analytically, or verbally. The image of an input value is the single output value yielded by the function rule. The preimage of an output value is the set of input values for which the function rule yields that output value.","order":2,"origin":"template"},{"id":"c-1.1.A.3","parentId":"c-1.1.A","code":"1.1.A.3","text":"A function is increasing over an interval of its domain if, as the input values increase, the output values always increase. That is, for all a and b in the interval, if a < b, then f(a) < f(b).","order":3,"origin":"template"},{"id":"c-1.1.A.4","parentId":"c-1.1.A","code":"1.1.A.4","text":"A function is decreasing over an interval of its domain if, as the input values increase, the output values always decrease. That is, for all a and b in the interval, if a < b, then f(a) > f(b).","order":4,"origin":"template"},{"id":"c-1.1.B","parentId":"c-1.1","code":"1.1.B","text":"Construct a graph representing two quantities that vary with respect to each other in a contextual scenario.","order":2,"origin":"template"},{"id":"c-1.1.B.1","parentId":"c-1.1.B","code":"1.1.B.1","text":"The graph of a function displays a set of input-output pairs and shows how the values of the function’s input and output values vary.","order":1,"origin":"template"},{"id":"c-1.1.B.2","parentId":"c-1.1.B","code":"1.1.B.2","text":"A verbal description of the way aspects of phenomena change together can be the basis for constructing a graph.","order":2,"origin":"template"},{"id":"c-1.1.B.3","parentId":"c-1.1.B","code":"1.1.B.3","text":"The graph of a function is concave up on intervals in which the rate of change is increasing.","order":3,"origin":"template"},{"id":"c-1.1.B.4","parentId":"c-1.1.B","code":"1.1.B.4","text":"The graph of a function is concave down on intervals in which the rate of change is decreasing.","order":4,"origin":"template"},{"id":"c-1.1.B.5","parentId":"c-1.1.B","code":"1.1.B.5","text":"The graph intersects the x-axis when the output value is zero. The corresponding input values are said to be zeros of the function.","order":5,"origin":"template"},{"id":"c-1.2.A","parentId":"c-1.2","code":"1.2.A","text":"Compare the rates of change at two points using average rates of change near the points.","order":1,"origin":"template"},{"id":"c-1.2.A.1","parentId":"c-1.2.A","code":"1.2.A.1","text":"The average rate of change of a function over an interval of the function’s domain is the constant rate of change that yields the same change in the output values as the function yielded on that interval of the function’s domain. It is the ratio of the change in the output values to the change in input values over that interval.","order":1,"origin":"template"},{"id":"c-1.2.A.2","parentId":"c-1.2.A","code":"1.2.A.2","text":"The rate of change of a function at a point quantifies the rate at which output values would change were the input values to change at that point. The rate of change at a point can be approximated by the average rates of change of the function over small intervals containing the point, if such values exist.","order":2,"origin":"template"},{"id":"c-1.2.A.3","parentId":"c-1.2.A","code":"1.2.A.3","text":"The rates of change at two points can be compared using average rate of change approximations over sufficiently small intervals containing each point, if such values exist.","order":3,"origin":"template"},{"id":"c-1.2.B","parentId":"c-1.2","code":"1.2.B","text":"Describe how two quantities vary together at different points and over different intervals of a function.","order":2,"origin":"template"},{"id":"c-1.2.B.1","parentId":"c-1.2.B","code":"1.2.B.1","text":"Rates of change quantify how two quantities vary together.","order":1,"origin":"template"},{"id":"c-1.2.B.2","parentId":"c-1.2.B","code":"1.2.B.2","text":"A positive rate of change indicates that as one quantity increases or decreases, the other quantity does the same.","order":2,"origin":"template"},{"id":"c-1.2.B.3","parentId":"c-1.2.B","code":"1.2.B.3","text":"A negative rate of change indicates that as one quantity increases, the other decreases.","order":3,"origin":"template"},{"id":"c-1.3.A","parentId":"c-1.3","code":"1.3.A","text":"Determine the average rates of change for sequences and functions, including linear, quadratic, and other function types.","order":1,"origin":"template"},{"id":"c-1.3.A.1","parentId":"c-1.3.A","code":"1.3.A.1","text":"For a linear function, the average rate of change over any length input-value interval is constant.","order":1,"origin":"template"},{"id":"c-1.3.A.2","parentId":"c-1.3.A","code":"1.3.A.2","text":"For a quadratic function, the average rates of change over consecutive equal-length input-value intervals can be given by a linear function.","order":2,"origin":"template"},{"id":"c-1.3.A.3","parentId":"c-1.3.A","code":"1.3.A.3","text":"The average rate of change of a function f over the closed interval [a, b] is the slope of the secant line from the point (a, f(a)) to (b, f(b)).","order":3,"origin":"template"},{"id":"c-1.3.B","parentId":"c-1.3","code":"1.3.B","text":"Determine the change in the average rates of change for linear, quadratic, and other function types.","order":2,"origin":"template"},{"id":"c-1.3.B.1","parentId":"c-1.3.B","code":"1.3.B.1","text":"For a linear function, since the average rates of change over consecutive equal-length input-value intervals can be given by a constant function, these average rates of change for a linear function are changing at a rate of zero.","order":1,"origin":"template"},{"id":"c-1.3.B.2","parentId":"c-1.3.B","code":"1.3.B.2","text":"For a quadratic function, since the average rates of change over consecutive equal-length input-value intervals can be given by a linear function, these average rates of change for a quadratic function are changing at a constant rate.","order":2,"origin":"template"},{"id":"c-1.3.B.3","parentId":"c-1.3.B","code":"1.3.B.3","text":"When the average rate of change over equal-length input-value intervals is increasing for all small-length intervals, the graph of the function is concave up. When the average rate of change over equal-length input-value intervals is decreasing for all small-length intervals, the graph of the function is concave down.","order":3,"origin":"template"},{"id":"c-1.4.A","parentId":"c-1.4","code":"1.4.A","text":"Identify key characteristics of polynomial functions related to rates of change.","order":1,"origin":"template"},{"id":"c-1.4.A.1","parentId":"c-1.4.A","code":"1.4.A.1","text":"A nonconstant polynomial function of x is any function representation that is equivalent to the analytical form p(x) = a_n x^n + a_(n−1) x^(n−1) + a_(n−2) x^(n−2) + ⋯ + a_2 x^2 + a_1 x + a_0, where n is a positive integer, a_i is a real number for each i from 0 to n, and a_n is nonzero. The polynomial has degree n, the leading term is a_n x^n, and the leading coefficient is a_n. A nonzero constant is also a polynomial function of degree zero.","order":1,"origin":"template"},{"id":"c-1.4.A.2","parentId":"c-1.4.A","code":"1.4.A.2","text":"Where a polynomial function switches between increasing and decreasing, or at the included endpoint of a polynomial with a restricted domain, the polynomial function will have a local, or relative, maximum or minimum output value. If any local maximum is greater than all other function output values, then that local maximum is a global, or absolute, maximum. Similarly, if any local minimum is less than all other function output values, then that local minimum is a global, or absolute, minimum.","order":2,"origin":"template"},{"id":"c-1.4.A.3","parentId":"c-1.4.A","code":"1.4.A.3","text":"Between every two distinct real zeros of a nonconstant polynomial function, there must be at least one input value corresponding to a local maximum or local minimum.","order":3,"origin":"template"},{"id":"c-1.4.A.4","parentId":"c-1.4.A","code":"1.4.A.4","text":"A polynomial function of even degree has either a global maximum or a global minimum. For a quadratic function, the global maximum or global minimum occurs at the vertex.","order":4,"origin":"template"},{"id":"c-1.4.A.5","parentId":"c-1.4.A","code":"1.4.A.5","text":"Points of inflection of a polynomial function occur at input values where the rate of change of the function changes from increasing to decreasing or from decreasing to increasing. This occurs where the graph of a polynomial function changes from concave up to concave down or from concave down to concave up.","order":5,"origin":"template"},{"id":"c-1.5.A","parentId":"c-1.5","code":"1.5.A","text":"Identify key characteristics of a polynomial function related to its zeros when suitable factorizations are available or with technology.","order":1,"origin":"template"},{"id":"c-1.5.A.1","parentId":"c-1.5.A","code":"1.5.A.1","text":"If a is a complex number and p(a) = 0, then a is called a zero of the polynomial function p, or a root of p(x) = 0. If a is a real number, then (x − a) is a linear factor of p if and only if a is a zero of p.","order":1,"origin":"template"},{"id":"c-1.5.A.2","parentId":"c-1.5.A","code":"1.5.A.2","text":"If a linear factor (x - a) is repeated n times, the corresponding zero of the polynomial function has a multiplicity n. A polynomial function of degree n has exactly n complex zeros when counting multiplicities.","order":2,"origin":"template"},{"id":"c-1.5.A.3","parentId":"c-1.5.A","code":"1.5.A.3","text":"If a is a real zero of a polynomial function p, then the graph of y = p(x) has an x-intercept at the point (a, 0). Consequently, real zeros of a polynomial can be endpoints for intervals satisfying polynomial inequalities.","order":3,"origin":"template"},{"id":"c-1.5.A.4","parentId":"c-1.5.A","code":"1.5.A.4","text":"If a + bi is a non-real zero of a polynomial function p, then its conjugate a − bi is also a zero of p.","order":4,"origin":"template"},{"id":"c-1.5.A.5","parentId":"c-1.5.A","code":"1.5.A.5","text":"If the real zero, a, of a polynomial function has even multiplicity, then the signs of the output values are the same for input values near x = a. For these polynomial functions, the graph will be tangent to the x-axis at x = a.","order":5,"origin":"template"},{"id":"c-1.5.A.6","parentId":"c-1.5.A","code":"1.5.A.6","text":"The degree of a polynomial function can be found by examining the successive differences of the output values over equal-interval input values. The degree of the polynomial function is equal to the least value n for which the successive nth differences are constant.","order":6,"origin":"template"},{"id":"c-1.5.B","parentId":"c-1.5","code":"1.5.B","text":"Determine if a polynomial function is even or odd.","order":2,"origin":"template"},{"id":"c-1.5.B.1","parentId":"c-1.5.B","code":"1.5.B.1","text":"An even function is graphically symmetric over the line x = 0 and analytically has the property f(−x) = f(x). If n is even, then a polynomial of the form p(x) = a_n x^n, where n ≥ 1 and a_n ≠ 0, is an even function.","order":1,"origin":"template"},{"id":"c-1.5.B.2","parentId":"c-1.5.B","code":"1.5.B.2","text":"An odd function is graphically symmetric about the point (0, 0) and analytically has the property f(−x) = −f(x). If n is odd, then a polynomial of the form p(x) = a_n x^n, where n ≥ 1 and a_n ≠ 0, is an odd function.","order":2,"origin":"template"},{"id":"c-1.6.A","parentId":"c-1.6","code":"1.6.A","text":"Describe end behaviors of polynomial functions.","order":1,"origin":"template"},{"id":"c-1.6.A.1","parentId":"c-1.6.A","code":"1.6.A.1","text":"As input values of a nonconstant polynomial function increase without bound, the output values will either increase or decrease without bound. The corresponding mathematical notation is lim p(x) = ∞ or lim p(x) = -∞. x→∞ x→∞","order":1,"origin":"template"},{"id":"c-1.6.A.2","parentId":"c-1.6.A","code":"1.6.A.2","text":"As input values of a nonconstant polynomial function decrease without bound, the output values will either increase or decrease without bound. The corresponding mathematical notation is lim p(x) = ∞or lim p(x) = -∞. x→-∞ x→-∞","order":2,"origin":"template"},{"id":"c-1.6.A.3","parentId":"c-1.6.A","code":"1.6.A.3","text":"The degree and sign of the leading term of a polynomial determines the end behavior of the polynomial function, because as the input values increase or decrease without bound, the values of the leading term dominate the values of all lower-degree terms.","order":3,"origin":"template"},{"id":"c-1.7.A","parentId":"c-1.7","code":"1.7.A","text":"Describe end behaviors of rational functions.","order":1,"origin":"template"},{"id":"c-1.7.A.1","parentId":"c-1.7.A","code":"1.7.A.1","text":"A rational function is analytically represented as a quotient of two polynomial functions and gives a measure of the relative size of the polynomial function in the numerator compared to the polynomial function in the denominator for each value in the rational function’s domain.","order":1,"origin":"template"},{"id":"c-1.7.A.2","parentId":"c-1.7.A","code":"1.7.A.2","text":"The end behavior of a rational function will be affected most by the polynomial with the greater degree, as its values will dominate the values of the rational function for input values of large magnitude. For input values of large magnitude, a polynomial is dominated by its leading term. Therefore, the end behavior of a rational function can be understood by examining the corresponding quotient of the leading terms.","order":2,"origin":"template"},{"id":"c-1.7.A.3","parentId":"c-1.7.A","code":"1.7.A.3","text":"If the polynomial in the numerator dominates the polynomial in the denominator for input values of large magnitude, then the quotient of the leading terms is a nonconstant polynomial, and the original rational function has the end behavior of that polynomial. If that polynomial is linear, then the graph of the rational function has a slant asymptote parallel to the graph of the line.","order":3,"origin":"template"},{"id":"c-1.7.A.4","parentId":"c-1.7.A","code":"1.7.A.4","text":"If neither polynomial in a rational function dominates the other for input values of large magnitude, then the quotient of the leading terms is a constant, and that constant indicates the location of a horizontal asymptote of the graph of the original rational function.","order":4,"origin":"template"},{"id":"c-1.7.A.5","parentId":"c-1.7.A","code":"1.7.A.5","text":"If the polynomial in the denominator dominates the polynomial in the numerator for input values of large magnitude, then the quotient of the leading terms is a rational function with a constant in the numerator and nonconstant polynomial in the denominator, and the graph of the original rational function has a horizontal asymptote at y = 0.","order":5,"origin":"template"},{"id":"c-1.7.A.6","parentId":"c-1.7.A","code":"1.7.A.6","text":"When the graph of a rational function r has a horizontal asymptote at y = b, where b is a constant, the output values of the rational function get arbitrarily close to b and stay arbitrarily close to b as input values increase or decrease without bound. The corresponding mathematical notation is lim (x→∞) r(x) = b or lim (x→−∞) r(x) = b.","order":6,"origin":"template"},{"id":"c-1.8.A","parentId":"c-1.8","code":"1.8.A","text":"Determine the zeros of rational functions.","order":1,"origin":"template"},{"id":"c-1.8.A.1","parentId":"c-1.8.A","code":"1.8.A.1","text":"The real zeros of a rational function correspond to the real zeros of the numerator for such values in its domain.","order":1,"origin":"template"},{"id":"c-1.8.A.2","parentId":"c-1.8.A","code":"1.8.A.2","text":"The real zeros of both polynomial functions of a rational function r are endpoints or asymptotes for intervals satisfying the rational function inequalities r(x) ≥ 0 or r(x) ≤ 0.","order":2,"origin":"template"},{"id":"c-1.9.A","parentId":"c-1.9","code":"1.9.A","text":"Determine vertical asymptotes of graphs of rational functions.","order":1,"origin":"template"},{"id":"c-1.9.A.1","parentId":"c-1.9.A","code":"1.9.A.1","text":"If the value a is a real zero of the polynomial function in the denominator of a rational function and is not also a real zero of the polynomial function in the numerator, then the graph of the rational function has a vertical asymptote at x = a. Furthermore, a vertical asymptote also occurs at x = a if the multiplicity of a as a real zero in the denominator is greater than its multiplicity as a real zero in the numerator.","order":1,"origin":"template"},{"id":"c-1.9.A.2","parentId":"c-1.9.A","code":"1.9.A.2","text":"Near a vertical asymptote, x = a, of a rational function, the values of the polynomial function in the denominator are arbitrarily close to zero, so the values of the rational function r increase or decrease without bound. The corresponding mathematical notation is lim (x→a⁺) r(x) = ∞ or lim (x→a⁺) r(x) = −∞ for input values near a and greater than a, and lim (x→a⁻) r(x) = ∞ or lim (x→a⁻) r(x) = −∞ for input values near a and less than a.","order":2,"origin":"template"},{"id":"c-1.10.A","parentId":"c-1.10","code":"1.10.A","text":"Determine holes in graphs of rational functions.","order":1,"origin":"template"},{"id":"c-1.10.A.1","parentId":"c-1.10.A","code":"1.10.A.1","text":"If the multiplicity of a real zero in the numerator is greater than or equal to its multiplicity in the denominator, then the graph of the rational function has a hole at the corresponding input value.","order":1,"origin":"template"},{"id":"c-1.10.A.2","parentId":"c-1.10.A","code":"1.10.A.2","text":"If the graph of a rational function r has a hole at x = c, then the location of the hole can be determined by examining the output values corresponding to input values sufficiently close to c. If input values sufficiently close to c correspond to output values arbitrarily close to L, then the hole is located at the point with coordinates (c, L). The corresponding mathematical notation is lim (x→c) r(x) = L. It should be noted that lim (x→c⁻) r(x) = lim (x→c⁺) r(x) = lim (x→c) r(x) = L.","order":2,"origin":"template"},{"id":"c-1.11.A","parentId":"c-1.11","code":"1.11.A","text":"Rewrite polynomial and rational expressions in equivalent forms.","order":1,"origin":"template"},{"id":"c-1.11.A.1","parentId":"c-1.11.A","code":"1.11.A.1","text":"Because the factored form of a polynomial or rational function readily provides information about real zeros, it can reveal information about x-intercepts, asymptotes, holes, domain, and range.","order":1,"origin":"template"},{"id":"c-1.11.A.2","parentId":"c-1.11.A","code":"1.11.A.2","text":"The standard form of a polynomial or rational function can reveal information about end behaviors of the function.","order":2,"origin":"template"},{"id":"c-1.11.A.3","parentId":"c-1.11.A","code":"1.11.A.3","text":"The information extracted from different analytic representations of the same polynomial or rational function can be used to answer questions in context.","order":3,"origin":"template"},{"id":"c-1.11.B","parentId":"c-1.11","code":"1.11.B","text":"Determine the quotient of two polynomial functions using long division.","order":2,"origin":"template"},{"id":"c-1.11.B.1","parentId":"c-1.11.B","code":"1.11.B.1","text":"Polynomial long division is an algebraic process similar to numerical long division involving a quotient and remainder. If the polynomial f is divided by the polynomial g, then f can be rewritten as f(x) = g(x)q(x) + r(x), where q is the quotient, r is the remainder, and the degree of r is less than the degree of g.","order":1,"origin":"template"},{"id":"c-1.11.B.2","parentId":"c-1.11.B","code":"1.11.B.2","text":"The result of polynomial long division is helpful in finding equations of slant asymptotes for graphs of rational functions.","order":2,"origin":"template"},{"id":"c-1.11.C","parentId":"c-1.11","code":"1.11.C","text":"Rewrite the repeated product of binomials using the binomial theorem.","order":3,"origin":"template"},{"id":"c-1.11.C.1","parentId":"c-1.11.C","code":"1.11.C.1","text":"The binomial theorem utilizes the entries in a single row of Pascal’s Triangle to more easily n expand expressions of the form (a + b), including polynomial functions of the form n p(x) (x= c)+, where c is a constant.","order":1,"origin":"template"},{"id":"c-1.12.A","parentId":"c-1.12","code":"1.12.A","text":"Construct a function that is an additive and/or multiplicative transformation of another function.","order":1,"origin":"template"},{"id":"c-1.12.A.1","parentId":"c-1.12.A","code":"1.12.A.1","text":"The function g(x) = f(x) + k is an additive transformation of the function f that results in a vertical translation of the graph of f by k units.","order":1,"origin":"template"},{"id":"c-1.12.A.2","parentId":"c-1.12.A","code":"1.12.A.2","text":"The function g(x) = f(x + h) is an additive transformation of the function f that results in a horizontal translation of the graph of f by −h units.","order":2,"origin":"template"},{"id":"c-1.12.A.3","parentId":"c-1.12.A","code":"1.12.A.3","text":"The function g(x) = af(x), where a ≠ 0, is a multiplicative transformation of the function f that results in a vertical dilation of the graph of f by a factor of |a|. If a < 0, the transformation involves a reflection over the x-axis.","order":3,"origin":"template"},{"id":"c-1.12.A.4","parentId":"c-1.12.A","code":"1.12.A.4","text":"The function g(x) = f(bx), where b ≠ 0, is a multiplicative transformation of the function f that results in a horizontal dilation of the graph of f by a factor of 1/|b|. If b < 0, the transformation involves a reflection over the y-axis.","order":4,"origin":"template"},{"id":"c-1.12.A.5","parentId":"c-1.12.A","code":"1.12.A.5","text":"Additive and multiplicative transformations can be combined, resulting in combinations of horizontal and vertical translations and dilations. The set of points prior to the transformations is called the preimage of the transformations, and the set of points after the transformations is called the image of the transformations.","order":5,"origin":"template"},{"id":"c-1.12.A.6","parentId":"c-1.12.A","code":"1.12.A.6","text":"The domain and range of a function that is a transformation of a parent function may be different from those of the parent function.","order":6,"origin":"template"},{"id":"c-1.13.A","parentId":"c-1.13","code":"1.13.A","text":"Identify an appropriate function type to construct a function model for a given scenario.","order":1,"origin":"template"},{"id":"c-1.13.A.1","parentId":"c-1.13.A","code":"1.13.A.1","text":"Linear functions model data sets or aspects of contextual scenarios that demonstrate roughly constant rates of change.","order":1,"origin":"template"},{"id":"c-1.13.A.2","parentId":"c-1.13.A","code":"1.13.A.2","text":"Quadratic functions model data sets or aspects of contextual scenarios that demonstrate roughly linear rates of change, or data sets that are roughly symmetric with a unique maximum or minimum value.","order":2,"origin":"template"},{"id":"c-1.13.A.3","parentId":"c-1.13.A","code":"1.13.A.3","text":"Geometric contexts involving area or two dimensions can often be modeled by quadratic functions. Geometric contexts involving volume or three dimensions can often be modeled by cubic functions.","order":3,"origin":"template"},{"id":"c-1.13.A.4","parentId":"c-1.13.A","code":"1.13.A.4","text":"Polynomial functions model data sets or contextual scenarios with multiple real zeros or multiple maxima or minima.","order":4,"origin":"template"},{"id":"c-1.13.A.5","parentId":"c-1.13.A","code":"1.13.A.5","text":"A polynomial function of degree n models data sets or contextual scenarios that demonstrate roughly constant nonzero nth differences.","order":5,"origin":"template"},{"id":"c-1.13.A.6","parentId":"c-1.13.A","code":"1.13.A.6","text":"A polynomial function of degree n or less can be used to model a graph of n + 1 points with distinct input values.","order":6,"origin":"template"},{"id":"c-1.13.A.7","parentId":"c-1.13.A","code":"1.13.A.7","text":"A piecewise-defined function consists of a set of functions defined over nonoverlapping domain intervals and is useful for modeling a data set or contextual scenario that demonstrates different characteristics over different intervals.","order":7,"origin":"template"},{"id":"c-1.13.B","parentId":"c-1.13","code":"1.13.B","text":"Describe assumptions and restrictions related to building a function model.","order":2,"origin":"template"},{"id":"c-1.13.B.1","parentId":"c-1.13.B","code":"1.13.B.1","text":"A model may have underlying assumptions about what is consistent in the model.","order":1,"origin":"template"},{"id":"c-1.13.B.2","parentId":"c-1.13.B","code":"1.13.B.2","text":"A model may have underlying assumptions about how quantities change together.","order":2,"origin":"template"},{"id":"c-1.13.B.3","parentId":"c-1.13.B","code":"1.13.B.3","text":"A model may require domain restrictions based on mathematical clues, contextual clues, or extreme values in the data set.","order":3,"origin":"template"},{"id":"c-1.13.B.4","parentId":"c-1.13.B","code":"1.13.B.4","text":"A model may require range restrictions, such as rounding values, based on mathematical clues, contextual clues, or extreme values in the data set.","order":4,"origin":"template"},{"id":"c-1.14.A","parentId":"c-1.14","code":"1.14.A","text":"Construct a linear, quadratic, cubic, quartic, polynomial of degree n, or related piecewise-defined function model.","order":1,"origin":"template"},{"id":"c-1.14.A.1","parentId":"c-1.14.A","code":"1.14.A.1","text":"A model can be constructed based on restrictions identified in a mathematical or contextual scenario.","order":1,"origin":"template"},{"id":"c-1.14.A.2","parentId":"c-1.14.A","code":"1.14.A.2","text":"A model of a data set or a contextual scenario can be constructed using transformations of the parent function.","order":2,"origin":"template"},{"id":"c-1.14.A.3","parentId":"c-1.14.A","code":"1.14.A.3","text":"A model of a data set can be constructed using technology and regressions, including linear, quadratic, cubic, and quartic regressions.","order":3,"origin":"template"},{"id":"c-1.14.A.4","parentId":"c-1.14.A","code":"1.14.A.4","text":"A piecewise-defined function model can be constructed through a combination of modeling techniques.","order":4,"origin":"template"},{"id":"c-1.14.B","parentId":"c-1.14","code":"1.14.B","text":"Construct a rational function model based on a context.","order":2,"origin":"template"},{"id":"c-1.14.B.1","parentId":"c-1.14.B","code":"1.14.B.1","text":"Data sets and aspects of contextual scenarios involving quantities that are inversely proportional can often be modeled by rational functions. For example, the magnitudes of both gravitational force and electromagnetic force between objects are inversely proportional to the objects’ squared distance.","order":1,"origin":"template"},{"id":"c-1.14.C","parentId":"c-1.14","code":"1.14.C","text":"Apply a function model to answer questions about a data set or contextual scenario.","order":3,"origin":"template"},{"id":"c-1.14.C.1","parentId":"c-1.14.C","code":"1.14.C.1","text":"A model can be used to draw conclusions about the modeled data set or contextual scenario, including answering key questions and predicting values, rates of change, average rates of change, and changing rates of change. Appropriate units of measure should be extracted or inferred from the given context.","order":1,"origin":"template"},{"id":"c-2.1.A","parentId":"c-2.1","code":"2.1.A","text":"Express arithmetic sequences found in mathematical and contextual scenarios as functions of the whole numbers.","order":1,"origin":"template"},{"id":"c-2.1.A.1","parentId":"c-2.1.A","code":"2.1.A.1","text":"A sequence is a function from the whole numbers to the real numbers. Consequently, the graph of a sequence consists of discrete points instead of a curve.","order":1,"origin":"template"},{"id":"c-2.1.A.2","parentId":"c-2.1.A","code":"2.1.A.2","text":"Successive terms in an arithmetic sequence have a common difference, or constant rate of change.","order":2,"origin":"template"},{"id":"c-2.1.A.3","parentId":"c-2.1.A","code":"2.1.A.3","text":"The general term of an arithmetic sequence with a common difference d is denoted by a_n and is given by a_n = a_0 + dn, where a_0 is the initial value, or by a_n = a_k + d(n − k), where a_k is the kth term of the sequence.","order":3,"origin":"template"},{"id":"c-2.1.B","parentId":"c-2.1","code":"2.1.B","text":"Express geometric sequences found in mathematical and contextual scenarios as functions of the whole numbers.","order":2,"origin":"template"},{"id":"c-2.1.B.1","parentId":"c-2.1.B","code":"2.1.B.1","text":"Successive terms in an increasing or decreasing geometric sequence have a common ratio, or constant proportional change.","order":1,"origin":"template"},{"id":"c-2.1.B.2","parentId":"c-2.1.B","code":"2.1.B.2","text":"The general term of an increasing or decreasing geometric sequence with a common ratio r is denoted by g_n and is given by g_n = g_0 r^n, where g_0 is the initial value, or by g_n = g_k r^(n−k), where g_k is the kth term of the sequence.","order":2,"origin":"template"},{"id":"c-2.1.B.3","parentId":"c-2.1.B","code":"2.1.B.3","text":"An increasing arithmetic sequence increases equally with each step, whereas an increasing geometric sequence of positive values increases by a larger amount with each successive step.","order":3,"origin":"template"},{"id":"c-2.2.A","parentId":"c-2.2","code":"2.2.A","text":"Construct functions of the real numbers that are comparable to arithmetic and geometric sequences.","order":1,"origin":"template"},{"id":"c-2.2.A.1","parentId":"c-2.2.A","code":"2.2.A.1","text":"Linear functions of the form f(x) = b + mx are similar to arithmetic sequences of the form a_n = a_0 + dn, as both can be expressed as an initial value (b or a_0) plus repeated addition of a constant rate of change, the slope (m or d).","order":1,"origin":"template"},{"id":"c-2.2.A.2","parentId":"c-2.2.A","code":"2.2.A.2","text":"Similar to arithmetic sequences of the form a_n = a_k + d(n − k), which are based on a known difference, d, and a kth term, linear functions can be expressed in the form f(x) = y_i + m(x − x_i) based on a known slope, m, and a point, (x_i, y_i).","order":2,"origin":"template"},{"id":"c-2.2.A.3","parentId":"c-2.2.A","code":"2.2.A.3","text":"Exponential functions of the form f(x) = ab^x are similar to geometric sequences of the form g_n = g_0 r^n, as both can be expressed as an initial value (a or g_0) times repeated multiplication by a constant ratio (b or r).","order":3,"origin":"template"},{"id":"c-2.2.A.4","parentId":"c-2.2.A","code":"2.2.A.4","text":"Similar to geometric sequences of the form g_n = g_k r^(n−k), which are based on a known ratio, r, and a kth term, exponential functions can be expressed in the form f(x) = y_i b^(x−x_i) based on a known ratio, b, and a point, (x_i, y_i).","order":4,"origin":"template"},{"id":"c-2.2.A.5","parentId":"c-2.2.A","code":"2.2.A.5","text":"Sequences and their corresponding functions may have different domains.","order":5,"origin":"template"},{"id":"c-2.2.B","parentId":"c-2.2","code":"2.2.B","text":"Describe similarities and differences between linear and exponential functions.","order":2,"origin":"template"},{"id":"c-2.2.B.1","parentId":"c-2.2.B","code":"2.2.B.1","text":"Over equal-length input-value intervals, if the output values of a function change at constant rate, then the function is linear; if the output values of a function change proportionally, then the function is exponential. For an exponential function, the known ratio cannot be 0 or 1.","order":1,"origin":"template"},{"id":"c-2.2.B.2","parentId":"c-2.2.B","code":"2.2.B.2","text":"Linear functions of the form f(x) = b + mx and exponential functions of the form f(x) = ab^x can both be expressed analytically in terms of an initial value and a constant involved with change. However, linear functions are based on addition, while exponential functions are based on multiplication.","order":2,"origin":"template"},{"id":"c-2.2.B.3","parentId":"c-2.2.B","code":"2.2.B.3","text":"Arithmetic sequences, linear functions, geometric sequences, and exponential functions all have the property that they can be determined by two distinct sequence or function values.","order":3,"origin":"template"},{"id":"c-2.3.A","parentId":"c-2.3","code":"2.3.A","text":"Identify key characteristics of exponential functions.","order":1,"origin":"template"},{"id":"c-2.3.A.1","parentId":"c-2.3.A","code":"2.3.A.1","text":"The general form of an exponential function is f(x) = ab^x, with the initial value a, where a ≠ 0, and the base b, where b > 0, and b ≠ 1. When a > 0 and b > 1, the exponential function is said to demonstrate exponential growth. When a > 0 and 0 < b < 1, the exponential function is said to demonstrate exponential decay.","order":1,"origin":"template"},{"id":"c-2.3.A.2","parentId":"c-2.3.A","code":"2.3.A.2","text":"When the natural numbers are input values in an exponential function, the input value specifies the number of factors of the base to be applied to the function’s initial value. The domain of an exponential function is all real numbers.","order":2,"origin":"template"},{"id":"c-2.3.A.3","parentId":"c-2.3.A","code":"2.3.A.3","text":"Because the output values of exponential functions in general form are proportional over equal-length input-value intervals, exponential functions are always increasing or always decreasing, and their graphs are always concave up or always concave down. Consequently, exponential functions do not have extrema except on a closed interval, and their graphs do not have points of inflection.","order":3,"origin":"template"},{"id":"c-2.3.A.4","parentId":"c-2.3.A","code":"2.3.A.4","text":"If the output values of the function f are not proportional over equal-length input-value intervals, but the output values of an additive transformation of f are proportional over equal-length input-value intervals, then f can be modeled by an additive transformation of an exponential function.","order":4,"origin":"template"},{"id":"c-2.3.A.5","parentId":"c-2.3.A","code":"2.3.A.5","text":"For an exponential function in general form, as the input values increase or decrease without bound, the output values will increase or decrease without bound or will get arbitrarily close to zero. That is, for an exponential x function in general form, lim ab = ∞, x→±∞ x x lim ab = -∞, or lim ab = 0. x→±∞ x→±∞","order":5,"origin":"template"},{"id":"c-2.4.A","parentId":"c-2.4","code":"2.4.A","text":"Rewrite exponential expressions in equivalent forms.","order":1,"origin":"template"},{"id":"c-2.4.A.1","parentId":"c-2.4.A","code":"2.4.A.1","text":"The product property for exponents states that b^m b^n = b^(m+n). Graphically, this property implies that every horizontal translation of an exponential function, f(x) = b^(x+k), is equivalent to a vertical dilation, f(x) = b^(x+k) = b^k b^x = ab^x, where a = b^k.","order":1,"origin":"template"},{"id":"c-2.4.A.2","parentId":"c-2.4.A","code":"2.4.A.2","text":"The power property for exponents states that (b^m)^n = b^(mn). Graphically, this property implies that every horizontal dilation of an exponential function, f(x) = b^(cx), is equivalent to a change of the base of an exponential function, f(x) = (b^c)^x, where b^c is a constant and c ≠ 0.","order":2,"origin":"template"},{"id":"c-2.4.A.3","parentId":"c-2.4.A","code":"2.4.A.3","text":"The negative exponent property states that -n 1 b =. n b","order":3,"origin":"template"},{"id":"c-2.4.A.4","parentId":"c-2.4.A","code":"2.4.A.4","text":"The value of an exponential expression involving an exponential unit fraction, such as (1/k) b where k is a natural number, is the kth root of b, when it exists.","order":4,"origin":"template"},{"id":"c-2.5.A","parentId":"c-2.5","code":"2.5.A","text":"Construct a model for situations involving proportional output values over equal-length input-value intervals.","order":1,"origin":"template"},{"id":"c-2.5.A.1","parentId":"c-2.5.A","code":"2.5.A.1","text":"Exponential functions model growth patterns where successive output values over equal-length input-value intervals are proportional. When the input values are whole numbers, exponential functions model situations of repeated multiplication of a constant to an initial value.","order":1,"origin":"template"},{"id":"c-2.5.A.2","parentId":"c-2.5.A","code":"2.5.A.2","text":"A constant may need to be added to the dependent variable values of a data set to reveal a proportional growth pattern.","order":2,"origin":"template"},{"id":"c-2.5.A.3","parentId":"c-2.5.A","code":"2.5.A.3","text":"An exponential function model can be constructed from an appropriate ratio and initial value or from two input-output pairs. The initial value and the base can be found by solving a system of equations resulting from the two input-output pairs.","order":3,"origin":"template"},{"id":"c-2.5.A.4","parentId":"c-2.5.A","code":"2.5.A.4","text":"Exponential function models can be constructed by applying transformations to f(x) = ab^x based on characteristics of a contextual scenario or data set.","order":4,"origin":"template"},{"id":"c-2.5.A.5","parentId":"c-2.5.A","code":"2.5.A.5","text":"Exponential function models can be constructed for a data set with technology using exponential regressions.","order":5,"origin":"template"},{"id":"c-2.5.A.6","parentId":"c-2.5.A","code":"2.5.A.6","text":"The natural base e, which is approximately 2.718, is often used as the base in exponential functions that model contextual scenarios.","order":6,"origin":"template"},{"id":"c-2.5.B","parentId":"c-2.5","code":"2.5.B","text":"Apply exponential models to answer questions about a data set or contextual scenario.","order":2,"origin":"template"},{"id":"c-2.5.B.1","parentId":"c-2.5.B","code":"2.5.B.1","text":"For an exponential model in general form f(x) = ab^x, the base of the exponent, b, can be understood as a growth factor in successive unit changes in the input values and is related to a percent change in context.","order":1,"origin":"template"},{"id":"c-2.5.B.2","parentId":"c-2.5.B","code":"2.5.B.2","text":"Equivalent forms of an exponential function can reveal different properties of the function. For example, if d represents number of days, then the base of f(d) = (2^(1/7))^d indicates that the quantity increases by a factor of 2^(1/7) every day, but the equivalent form f(d) = 2^(d/7) indicates that the quantity increases by a factor of 2 every week.","order":2,"origin":"template"},{"id":"c-2.5.B.3","parentId":"c-2.5.B","code":"2.5.B.3","text":"Exponential models can be used to predict values for the dependent variable, depending on the contextual constraints on the domain, and may be used to determine values of the independent variable.","order":3,"origin":"template"},{"id":"c-2.6.A","parentId":"c-2.6","code":"2.6.A","text":"Construct linear, quadratic, and exponential models based on a data set.","order":1,"origin":"template"},{"id":"c-2.6.A.1","parentId":"c-2.6.A","code":"2.6.A.1","text":"Two variables in a data set that demonstrate a slightly changing rate of change can be modeled by linear, quadratic, and exponential function models.","order":1,"origin":"template"},{"id":"c-2.6.A.2","parentId":"c-2.6.A","code":"2.6.A.2","text":"Models can be compared based on contextual clues and applicability to determine which model is most appropriate.","order":2,"origin":"template"},{"id":"c-2.6.B","parentId":"c-2.6","code":"2.6.B","text":"Validate a model constructed from a data set.","order":2,"origin":"template"},{"id":"c-2.6.B.1","parentId":"c-2.6.B","code":"2.6.B.1","text":"For a given value of an independent variable, a residual of a regression is the actual value of the dependent variable value minus the value predicted by the function regression model. A residual plot is a graphical representation of the residuals of a regression, with the residuals on the vertical axis and the independent variable on the horizontal axis. A model is justified as appropriate for a data set if the residual plot appears without pattern.","order":1,"origin":"template"},{"id":"c-2.6.B.2","parentId":"c-2.6.B","code":"2.6.B.2","text":"For given values of an independent variable, the errors in a model can relate to the signed differences in the values of the dependent variable predicted by the function regression model and the actual values OR the unsigned absolute values of the residuals. Errors may reveal that the model underestimates or overestimates actual values on a given input-value interval. The data set and context can provide clues as to whether underestimates or overestimates are preferred on a given input-value interval.","order":2,"origin":"template"},{"id":"c-2.7.A","parentId":"c-2.7","code":"2.7.A","text":"Evaluate the composition of two or more functions for given values.","order":1,"origin":"template"},{"id":"c-2.7.A.1","parentId":"c-2.7.A","code":"2.7.A.1","text":"If f and g are functions, the composite function f ∘ g maps a set of input values to a set of output values such that the output values of g are used as input values of f. For this reason, the domain of the composite function is restricted to those input values of g for which the corresponding output value is in the domain of f. (f ∘ g)(x) can also be represented as f(g(x)).","order":1,"origin":"template"},{"id":"c-2.7.A.2","parentId":"c-2.7.A","code":"2.7.A.2","text":"Values for the composite function f ∘ g can be calculated or estimated from the graphical, numerical, analytical, or verbal representations of f and g by using output values from g as input values for f.","order":2,"origin":"template"},{"id":"c-2.7.A.3","parentId":"c-2.7.A","code":"2.7.A.3","text":"The composition of functions is not commutative; that is, f ∘ g and g ∘ f are typically different functions; therefore, f(g(x)) and g(f(x)) are typically different values.","order":3,"origin":"template"},{"id":"c-2.7.A.4","parentId":"c-2.7.A","code":"2.7.A.4","text":"If the function f(x) = x is composed with any function g, the resulting composite function is the same as g; that is, g(f(x)) = f(g(x)) = g(x). The function f(x) = x is called the identity function. When composing two functions, the identity function acts in the same way as 0, the additive identity, when adding two numbers and 1, the multiplicative identity, when multiplying two numbers.","order":4,"origin":"template"},{"id":"c-2.7.B","parentId":"c-2.7","code":"2.7.B","text":"Construct a representation of the composition of two or more functions.","order":2,"origin":"template"},{"id":"c-2.7.B.1","parentId":"c-2.7.B","code":"2.7.B.1","text":"Function composition is useful for relating two quantities that are not directly related by an existing formula.","order":1,"origin":"template"},{"id":"c-2.7.B.2","parentId":"c-2.7.B","code":"2.7.B.2","text":"When analytic representations of the functions f and g are available, an analytic representation of f(g(x)) can be constructed by substituting g(x) for every instance of x in f.","order":2,"origin":"template"},{"id":"c-2.7.B.3","parentId":"c-2.7.B","code":"2.7.B.3","text":"A numerical or graphical representation of f ∘ g can often be constructed by calculating or estimating values for (x, f(g(x))).","order":3,"origin":"template"},{"id":"c-2.7.C","parentId":"c-2.7","code":"2.7.C","text":"Rewrite a given function as a composition of two or more functions.","order":3,"origin":"template"},{"id":"c-2.7.C.1","parentId":"c-2.7.C","code":"2.7.C.1","text":"Functions given analytically can often be decomposed into less complicated functions. When properly decomposed, the variable in one function should replace each instance of the function with which it was composed.","order":1,"origin":"template"},{"id":"c-2.7.C.2","parentId":"c-2.7.C","code":"2.7.C.2","text":"An additive transformation of a function, f, that results in vertical and horizontal translations can be understood as the composition of g(x) = x + k with f.","order":2,"origin":"template"},{"id":"c-2.7.C.3","parentId":"c-2.7.C","code":"2.7.C.3","text":"A multiplicative transformation of a function, f, that results in vertical and horizontal dilations can be understood as the composition of g(x) = kx with f.","order":3,"origin":"template"},{"id":"c-2.8.A","parentId":"c-2.8","code":"2.8.A","text":"Determine the input-output pairs of the inverse of a function.","order":1,"origin":"template"},{"id":"c-2.8.A.1","parentId":"c-2.8.A","code":"2.8.A.1","text":"On a specified domain, a function, f, has an inverse function, or is invertible, if each output value of f is mapped from a unique input value. The domain of a function may be restricted in many ways to make the function invertible.","order":1,"origin":"template"},{"id":"c-2.8.A.2","parentId":"c-2.8.A","code":"2.8.A.2","text":"An inverse function can be thought of as a reverse mapping of the function. An inverse function, f⁻¹, maps the output values of a function, f, on its invertible domain to their corresponding input values; that is, if f(a) = b, then f⁻¹(b) = a. Alternately, on its invertible domain, if a function consists of input-output pairs (a, b), then the inverse function consists of input-output pairs (b, a).","order":2,"origin":"template"},{"id":"c-2.8.B","parentId":"c-2.8","code":"2.8.B","text":"Determine the inverse of a function on an invertible domain.","order":2,"origin":"template"},{"id":"c-2.8.B.1","parentId":"c-2.8.B","code":"2.8.B.1","text":"The composition of a function, f, and its inverse function, f⁻¹, is the identity function; that is, f(f⁻¹(x)) = f⁻¹(f(x)) = x.","order":1,"origin":"template"},{"id":"c-2.8.B.2","parentId":"c-2.8.B","code":"2.8.B.2","text":"On a function’s invertible domain, the function’s range and domain are the inverse function’s domain and range, respectively. The inverse of the table of values of y = f(x) can be found by reversing the input-output pairs; that is,(a, b) corresponds to(b, a).","order":2,"origin":"template"},{"id":"c-2.8.B.3","parentId":"c-2.8.B","code":"2.8.B.3","text":"The inverse of the graph of the function y = f(x) can be found by reversing the roles of the x- and y-axes; that is, by reflecting the graph of the function over the graph of the identity function h(x) = x.","order":3,"origin":"template"},{"id":"c-2.8.B.4","parentId":"c-2.8.B","code":"2.8.B.4","text":"The inverse of the function can be found by determining the inverse operations to reverse the mapping. One method for finding the inverse of the function f is reversing the roles of x and y in the equation y = f(x), then solving for y = f⁻¹(x).","order":4,"origin":"template"},{"id":"c-2.8.B.5","parentId":"c-2.8.B","code":"2.8.B.5","text":"In addition to limiting the domain of a function to obtain an inverse function, contextual restrictions may also limit the applicability of an inverse function.","order":5,"origin":"template"},{"id":"c-2.9.A","parentId":"c-2.9","code":"2.9.A","text":"Evaluate logarithmic expressions.","order":1,"origin":"template"},{"id":"c-2.9.A.1","parentId":"c-2.9.A","code":"2.9.A.1","text":"The logarithmic expression log_b c is equal to, or represents, the value that the base b must be exponentially raised to in order to obtain the value c. That is, log_b c = a if and only if b^a = c, where a and c are constants, b > 0, and b ≠ 1. (When the base of a logarithmic expression is not specified, it is understood as the common logarithm with a base of 10.)","order":1,"origin":"template"},{"id":"c-2.9.A.2","parentId":"c-2.9.A","code":"2.9.A.2","text":"The values of some logarithmic expressions are readily accessible through basic arithmetic while other values can be estimated through the use of technology.","order":2,"origin":"template"},{"id":"c-2.9.A.3","parentId":"c-2.9.A","code":"2.9.A.3","text":"On a logarithmic scale, each unit represents a multiplicative change of the base of the logarithm. For example, on a standard scale, the units might be 0,,1 2,, while on a... logarithmic scale, using logarithm base 10, the units might be 10, 10., 10,...","order":3,"origin":"template"},{"id":"c-2.10.A","parentId":"c-2.10","code":"2.10.A","text":"Construct representations of the inverse of an exponential function with an initial value of 1.","order":1,"origin":"template"},{"id":"c-2.10.A.1","parentId":"c-2.10.A","code":"2.10.A.1","text":"The general form of a logarithmic function is f(x) = a log_b x, with base b, where b > 0, b ≠ 1, and a ≠ 0.","order":1,"origin":"template"},{"id":"c-2.10.A.2","parentId":"c-2.10.A","code":"2.10.A.2","text":"The way in which input and output values vary together have an inverse relationship in exponential and logarithmic functions. Output values of general-form exponential functions change proportionately as input values increase in equal-length intervals. However, input values of general-form logarithmic functions change proportionately as output values increase in equal-length intervals. Alternately, exponential growth is characterized by output values changing multiplicatively as input values change additively, whereas logarithmic growth is characterized by output values changing additively as input values change multiplicatively.","order":2,"origin":"template"},{"id":"c-2.10.A.3","parentId":"c-2.10.A","code":"2.10.A.3","text":"f(x) = log_b x and g(x) = b^x, where b > 0 and b ≠ 1, are inverse functions. That is, g(f(x)) = f(g(x)) = x.","order":3,"origin":"template"},{"id":"c-2.10.A.4","parentId":"c-2.10.A","code":"2.10.A.4","text":"The graph of the logarithmic function f(x) = log_b x, where b > 0 and b ≠ 1, is a reflection of the graph of the exponential function g(x) = b^x, where b > 0 and b ≠ 1, over the graph of the identity function h(x) = x.","order":4,"origin":"template"},{"id":"c-2.10.A.5","parentId":"c-2.10.A","code":"2.10.A.5","text":"If (s, t) is an ordered pair of the exponential function g(x) = b^x, where b > 0 and b ≠ 1, then (t, s) is an ordered pair of the logarithmic function f(x) = log_b x, where b > 0 and b ≠ 1.","order":5,"origin":"template"},{"id":"c-2.11.A","parentId":"c-2.11","code":"2.11.A","text":"Identify key characteristics of logarithmic functions.","order":1,"origin":"template"},{"id":"c-2.11.A.1","parentId":"c-2.11.A","code":"2.11.A.1","text":"The domain of a logarithmic function in general form is any real number greater than zero, and its range is all real numbers.","order":1,"origin":"template"},{"id":"c-2.11.A.2","parentId":"c-2.11.A","code":"2.11.A.2","text":"Because logarithmic functions are inverses of exponential functions, logarithmic functions are also always increasing or always decreasing, and their graphs are either always concave up or always concave down. Consequently, logarithmic functions do not have extrema except on a closed interval, and their graphs do not have points of inflection.","order":2,"origin":"template"},{"id":"c-2.11.A.3","parentId":"c-2.11.A","code":"2.11.A.3","text":"The additive transformation function g(x) = f(x + k), where k ≠ 0, of a logarithmic function f in general form does not have input values that are proportional over equal-length output-value intervals. However, if the input values of the additive transformation function, g(x) = f(x + k), of any function f are proportional over equal-length output value intervals, then f is logarithmic.","order":3,"origin":"template"},{"id":"c-2.11.A.4","parentId":"c-2.11.A","code":"2.11.A.4","text":"With their limited domain, logarithmic functions in general form are vertically asymptotic to x = 0, with an end behavior that is unbounded. That is, for a logarithmic function in general form, lim (x→0⁺) a log_b x = ±∞ and lim (x→∞) a log_b x = ±∞.","order":4,"origin":"template"},{"id":"c-2.12.A","parentId":"c-2.12","code":"2.12.A","text":"Rewrite logarithmic expressions in equivalent forms.","order":1,"origin":"template"},{"id":"c-2.12.A.1","parentId":"c-2.12.A","code":"2.12.A.1","text":"The product property for logarithms states that log_b(xy) = log_b x + log_b y. Graphically, this property implies that every horizontal dilation of a logarithmic function, f(x) = log_b(kx), is equivalent to a vertical translation, f(x) = log_b(kx) = log_b k + log_b x = a + log_b x, where a = log_b k.","order":1,"origin":"template"},{"id":"c-2.12.A.2","parentId":"c-2.12.A","code":"2.12.A.2","text":"The power property for logarithms states that log_b x^n = n log_b x. Graphically, this property implies that raising the input of a logarithmic function to a power, f(x) = log_b x^k, results in a vertical dilation, f(x) = k log_b x.","order":2,"origin":"template"},{"id":"c-2.12.A.3","parentId":"c-2.12.A","code":"2.12.A.3","text":"The change of base property for logarithms states that log_b x = log_a x / log_a b, where a > 0 and a ≠ 1. This implies that all logarithmic functions are vertical dilations of each other.","order":3,"origin":"template"},{"id":"c-2.12.A.4","parentId":"c-2.12.A","code":"2.12.A.4","text":"The function f(x) = ln x is a logarithmic function with the natural base e; that is, ln x = log_e x.","order":4,"origin":"template"},{"id":"c-2.13.A","parentId":"c-2.13","code":"2.13.A","text":"Solve exponential and logarithmic equations and inequalities.","order":1,"origin":"template"},{"id":"c-2.13.A.1","parentId":"c-2.13.A","code":"2.13.A.1","text":"Properties of exponents, properties of logarithms, and the inverse relationship between exponential and logarithmic functions can be used to solve equations and inequalities involving exponents and logarithms.","order":1,"origin":"template"},{"id":"c-2.13.A.2","parentId":"c-2.13.A","code":"2.13.A.2","text":"When solving exponential and logarithmic equations found through analytical or graphical methods, the results should be examined for extraneous solutions precluded by the mathematical or contextual limitations.","order":2,"origin":"template"},{"id":"c-2.13.A.3","parentId":"c-2.13.A","code":"2.13.A.3","text":"Logarithms can be used to rewrite expressions involving exponential functions in different ways that may reveal helpful information. Specifically, b^x = c^((log_c b)(x)).","order":3,"origin":"template"},{"id":"c-2.13.B","parentId":"c-2.13","code":"2.13.B","text":"Construct the inverse function for exponential and logarithmic functions.","order":2,"origin":"template"},{"id":"c-2.13.B.1","parentId":"c-2.13.B","code":"2.13.B.1","text":"The function f(x) = ab^(x+h) + k is a combination of additive transformations of an exponential function in general form. The inverse of y = f(x) can be found by determining the inverse operations to reverse the mapping.","order":1,"origin":"template"},{"id":"c-2.13.B.2","parentId":"c-2.13.B","code":"2.13.B.2","text":"The function f(x) = a log_b(x + h) + k is a combination of additive transformations of a logarithmic function in general form. The inverse of y = f(x) can be found by determining the inverse operations to reverse the mapping.","order":2,"origin":"template"},{"id":"c-2.14.A","parentId":"c-2.14","code":"2.14.A","text":"Construct a logarithmic function model.","order":1,"origin":"template"},{"id":"c-2.14.A.1","parentId":"c-2.14.A","code":"2.14.A.1","text":"Logarithmic functions are inverses of exponential functions and can be used to model situations involving proportional growth, or repeated multiplication, where the input values change proportionally over equal-length output-value intervals. Alternately, if the output value is a whole number, it indicates how many times the initial value has been multiplied by the proportion.","order":1,"origin":"template"},{"id":"c-2.14.A.2","parentId":"c-2.14.A","code":"2.14.A.2","text":"A logarithmic function model can be constructed from an appropriate proportion and a real zero or from two input-output pairs.","order":2,"origin":"template"},{"id":"c-2.14.A.3","parentId":"c-2.14.A","code":"2.14.A.3","text":"Logarithmic function models can be constructed by applying transformations to f(x) = a log_b x based on characteristics of a context or data set.","order":3,"origin":"template"},{"id":"c-2.14.A.4","parentId":"c-2.14.A","code":"2.14.A.4","text":"Logarithmic function models can be constructed for a data set with technology using logarithmic regressions.","order":4,"origin":"template"},{"id":"c-2.14.A.5","parentId":"c-2.14.A","code":"2.14.A.5","text":"The natural logarithm function is often useful in modeling real-world phenomena.","order":5,"origin":"template"},{"id":"c-2.14.A.6","parentId":"c-2.14.A","code":"2.14.A.6","text":"Logarithmic function models can be used to predict values for the dependent variable, and they may be used to determine values of the independent variable.","order":6,"origin":"template"},{"id":"c-2.15.A","parentId":"c-2.15","code":"2.15.A","text":"Determine if an exponential model is appropriate by examining a semi-log plot of a data set.","order":1,"origin":"template"},{"id":"c-2.15.A.1","parentId":"c-2.15.A","code":"2.15.A.1","text":"In a semi-log plot, one of the axes is logarithmically scaled with logarithm base n, where n > 1. When the y-axis of a semi-log plot is logarithmically scaled, data or functions that demonstrate exponential characteristics will appear linear.","order":1,"origin":"template"},{"id":"c-2.15.A.2","parentId":"c-2.15.A","code":"2.15.A.2","text":"If for large input values of a bivariate data set the logarithms of the output values trend linear, then transformations of an exponential function can be used to model the data set. Therefore, an advantage of semi-log plots is that the dependent variable values do not need to be transformed by a constant to reveal that transformations of an exponential function would produce an appropriate model.","order":2,"origin":"template"},{"id":"c-2.15.B","parentId":"c-2.15","code":"2.15.B","text":"Construct the linearization of exponential data.","order":2,"origin":"template"},{"id":"c-2.15.B.1","parentId":"c-2.15.B","code":"2.15.B.1","text":"Techniques used to model linear functions can be applied to a semi-log graph.","order":1,"origin":"template"},{"id":"c-2.15.B.2","parentId":"c-2.15.B","code":"2.15.B.2","text":"For an exponential model of the form y = ab^x, the corresponding linear model for the semi-log plot is y = (log_n b)x + log_n a, where n > 0 and n ≠ 1. Specifically, the linear rate of change is log_n b, and the initial linear value is log_n a.","order":2,"origin":"template"},{"id":"c-3.1.A","parentId":"c-3.1","code":"3.1.A","text":"Construct graphs of periodic relationships based on verbal representations.","order":1,"origin":"template"},{"id":"c-3.1.A.1","parentId":"c-3.1.A","code":"3.1.A.1","text":"A periodic relationship can be identified between two aspects of a context if, as the input values increase, the output values demonstrate a repeating pattern over successive equal-length intervals.","order":1,"origin":"template"},{"id":"c-3.1.A.2","parentId":"c-3.1.A","code":"3.1.A.2","text":"The graph of a periodic relationship can be constructed from the graph of a single cycle of the relationship.","order":2,"origin":"template"},{"id":"c-3.1.B","parentId":"c-3.1","code":"3.1.B","text":"Describe key characteristics of a periodic function based on a verbal representation.","order":2,"origin":"template"},{"id":"c-3.1.B.1","parentId":"c-3.1.B","code":"3.1.B.1","text":"The period of the function is the smallest positive value k such that f(x + k) = f(x) for all x in the domain. Consequently, the behavior of a periodic function is completely determined by any interval of width k.","order":1,"origin":"template"},{"id":"c-3.1.B.2","parentId":"c-3.1.B","code":"3.1.B.2","text":"The period can be estimated by investigating successive equal-length output values and finding where the pattern begins to repeat.","order":2,"origin":"template"},{"id":"c-3.1.B.3","parentId":"c-3.1.B","code":"3.1.B.3","text":"Periodic functions take on characteristics of other functions, such as intervals of increase and decrease, different concavities, and various rates of change. However, with periodic functions, all characteristics found in one period of the function will be in every period of the function.","order":3,"origin":"template"},{"id":"c-3.2.A","parentId":"c-3.2","code":"3.2.A","text":"Determine the sine, cosine, and tangent of an angle using the unit circle.","order":1,"origin":"template"},{"id":"c-3.2.A.1","parentId":"c-3.2.A","code":"3.2.A.1","text":"In the coordinate plane, an angle is in standard position when the vertex coincides with the origin and one ray coincides with the positive x-axis. The other ray is called the terminal ray. Positive and negative angle measures indicate rotations from the positive x-axis in the counterclockwise and clockwise direction, respectively. Angles in standard position that share a terminal ray differ by an integer number of revolutions.","order":1,"origin":"template"},{"id":"c-3.2.A.2","parentId":"c-3.2.A","code":"3.2.A.2","text":"When considering a circle centered at the origin, the radian measure of an angle in standard position is the ratio of the length of the arc of the circle that the angle subtends to the radius of that same circle. For a unit circle, which has radius 1, one radian is the measure of the angle subtended at the center of the circle by an arc that has length 1.","order":2,"origin":"template"},{"id":"c-3.2.A.3","parentId":"c-3.2.A","code":"3.2.A.3","text":"Given an angle in standard position and a circle centered at the origin, there is a point, P, where the terminal ray intersects the circle. The sine of the angle is the ratio of the vertical displacement of P from the x-axis to the distance between the origin and point P. Therefore, for a unit circle, the sine of the angle is the y-coordinate of point P.","order":3,"origin":"template"},{"id":"c-3.2.A.4","parentId":"c-3.2.A","code":"3.2.A.4","text":"Given an angle in standard position and a circle centered at the origin, there is a point, P, where the terminal ray intersects the circle. The cosine of the angle is the ratio of the horizontal displacement of P from the y-axis to the distance between the origin and point P. Therefore, for a unit circle, the cosine of the angle is the x-coordinate of point P.","order":4,"origin":"template"},{"id":"c-3.2.A.5","parentId":"c-3.2.A","code":"3.2.A.5","text":"Given an angle in standard position, the tangent of the angle is the slope, if it exists, of the terminal ray. Because the slope of the terminal ray is the ratio of the vertical displacement to the horizontal displacement over any interval, the tangent of the angle is the ratio of the y-coordinate to the x-coordinate of the point at which the terminal ray intersects the unit circle; alternately, it is the ratio of the angle’s sine to its cosine.","order":5,"origin":"template"},{"id":"c-3.3.A","parentId":"c-3.3","code":"3.3.A","text":"Determine coordinates of points on a circle centered at the origin.","order":1,"origin":"template"},{"id":"c-3.3.A.1","parentId":"c-3.3.A","code":"3.3.A.1","text":"Given an angle of measure θ in standard position and a circle with radius r centered at the origin, there is a point, P, where the terminal ray intersects the circle. The coordinates of point P are (r co θs r,sin θ).","order":1,"origin":"template"},{"id":"c-3.3.A.2","parentId":"c-3.3.A","code":"3.3.A.2","text":"The geometry of isosceles right and equilateral triangles, while attending to the signs of the values based on the quadrant of the angle, can be used to find exact values for the cosine and sine of angles that are multiples of π/4 and π/6 radians and whose terminal rays do not lie on an axis.","order":2,"origin":"template"},{"id":"c-3.4.A","parentId":"c-3.4","code":"3.4.A","text":"Construct representations of the sine and cosine functions using the unit circle.","order":1,"origin":"template"},{"id":"c-3.4.A.1","parentId":"c-3.4.A","code":"3.4.A.1","text":"Given an angle of measure θ in standard position and a unit circle centered at the origin, there is a point, P, where the terminal ray intersects the circle. The sine function, f(θ) = sin θ, gives the y-coordinate, or vertical displacement from the x-axis, of point P. The domain of the sine function is all real numbers.","order":1,"origin":"template"},{"id":"c-3.4.A.2","parentId":"c-3.4.A","code":"3.4.A.2","text":"As the input values, or angle measures, of the sine function increase, the output values oscillate between −1 and 1, taking every value in between and tracking the vertical displacement of points on the unit circle from the x-axis.","order":2,"origin":"template"},{"id":"c-3.4.A.3","parentId":"c-3.4.A","code":"3.4.A.3","text":"Given an angle of measure θ in standard position and a unit circle centered at the origin, there is a point, P, where the terminal ray intersects the circle. The cosine function, f(θ) = cos θ, gives the x-coordinate, or horizontal displacement from the y-axis, of point P. The domain of the cosine function is all real numbers.","order":3,"origin":"template"},{"id":"c-3.4.A.4","parentId":"c-3.4.A","code":"3.4.A.4","text":"As the input values, or angle measures, of the cosine function increase, the output values oscillate between −1 and 1, taking every value in between and tracking the horizontal displacement of points on the unit circle from the y-axis.","order":4,"origin":"template"},{"id":"c-3.5.A","parentId":"c-3.5","code":"3.5.A","text":"Identify key characteristics of the sine and cosine functions.","order":1,"origin":"template"},{"id":"c-3.5.A.1","parentId":"c-3.5.A","code":"3.5.A.1","text":"A sinusoidal function is any function that involves additive and multiplicative transformations of f(θ) = sin θ. The sine and cosine functions are both sinusoidal functions, with cos θ = sin(θ + π/2).","order":1,"origin":"template"},{"id":"c-3.5.A.2","parentId":"c-3.5.A","code":"3.5.A.2","text":"The period and frequency of a sinusoidal function are reciprocals. The period of f(θ) = sin θ and g(θ) = cos θ is 2π, and the frequency is 1/(2π).","order":2,"origin":"template"},{"id":"c-3.5.A.3","parentId":"c-3.5.A","code":"3.5.A.3","text":"The amplitude of a sinusoidal function is half the difference between its maximum and minimum values. The amplitude of f(θ) = sin θ and g(θ) = cos θ is 1.","order":3,"origin":"template"},{"id":"c-3.5.A.4","parentId":"c-3.5.A","code":"3.5.A.4","text":"The midline of the graph of a sinusoidal function is determined by the average, or arithmetic mean, of the maximum and minimum values of the function. The midline of the graphs of y = sin θ and y = cos θ is y = 0.","order":4,"origin":"template"},{"id":"c-3.5.A.5","parentId":"c-3.5.A","code":"3.5.A.5","text":"As input values increase, the graphs of sinusoidal functions oscillate between concave down and concave up.","order":5,"origin":"template"},{"id":"c-3.5.A.6","parentId":"c-3.5.A","code":"3.5.A.6","text":"The graph of y = sin θ has rotational symmetry about the origin and is therefore an odd function. The graph of y = cos θ has reflective symmetry over the y-axis and is therefore an even function.","order":6,"origin":"template"},{"id":"c-3.6.A","parentId":"c-3.6","code":"3.6.A","text":"Identify the amplitude, vertical shift, period, and phase shift of a sinusoidal function.","order":1,"origin":"template"},{"id":"c-3.6.A.1","parentId":"c-3.6.A","code":"3.6.A.1","text":"Functions that can be written in the form f(θ) = a sin(b(θ + c)) + d or g(θ) = a cos(b(θ + c)) + d, where a, b, c, and d are real numbers, a ≠ 0, and b ≠ 0, are sinusoidal functions and are transformations of the sine and cosine functions. Additive and multiplicative transformations are the same for both sine and cosine because the cosine function is a phase shift of the sine function by −π/2 units.","order":1,"origin":"template"},{"id":"c-3.6.A.2","parentId":"c-3.6.A","code":"3.6.A.2","text":"The graph of the additive transformation g(θ) = sin θ + d of the sine function f(θ) = sin θ is a vertical translation of the graph of f, including its midline, by d units. The same transformation of the cosine function yields the same result.","order":2,"origin":"template"},{"id":"c-3.6.A.3","parentId":"c-3.6.A","code":"3.6.A.3","text":"The graph of the additive transformation g(θ) = sin(θ + c) of the sine function f(θ) = sin θ is a horizontal translation, or phase shift, of the graph of f by −c units. The same transformation of the cosine function yields the same result.","order":3,"origin":"template"},{"id":"c-3.6.A.4","parentId":"c-3.6.A","code":"3.6.A.4","text":"The graph of the multiplicative transformation g(θ) = a sin θ of the sine function f(θ) = sin θ is a vertical dilation of the graph of f and differs in amplitude by a factor of |a|. The same transformation of the cosine function yields the same result.","order":4,"origin":"template"},{"id":"c-3.6.A.5","parentId":"c-3.6.A","code":"3.6.A.5","text":"The graph of the multiplicative transformation g(θ) = sin(bθ) of the sine function f(θ) = sin θ is a horizontal dilation of the graph of f and differs in period by a factor of 1/|b|. The same transformation of the cosine function yields the same result.","order":5,"origin":"template"},{"id":"c-3.6.A.6","parentId":"c-3.6.A","code":"3.6.A.6","text":"The graph of y = f(θ) = a sin(b(θ + c)) + d has an amplitude of |a| units, a period of 2π/|b| units, a midline vertical shift of d units from y = 0, and a phase shift of −c units. The same transformations of the cosine function yield the same results.","order":6,"origin":"template"},{"id":"c-3.7.A","parentId":"c-3.7","code":"3.7.A","text":"Construct sinusoidal function models of periodic phenomena.","order":1,"origin":"template"},{"id":"c-3.7.A.1","parentId":"c-3.7.A","code":"3.7.A.1","text":"The smallest interval of input values over which the maximum or minimum output values start to repeat, that is, the input-value interval between consecutive maxima or consecutive minima, can be used to determine or estimate the period and frequency for a sinusoidal function model.","order":1,"origin":"template"},{"id":"c-3.7.A.2","parentId":"c-3.7.A","code":"3.7.A.2","text":"The maximum and minimum output values can be used to determine or estimate the amplitude and vertical shift for a sinusoidal function model.","order":2,"origin":"template"},{"id":"c-3.7.A.3","parentId":"c-3.7.A","code":"3.7.A.3","text":"An actual pair of input-output values can be compared to pairs of input-output values produced by a sinusoidal function model to determine or estimate a phase shift for the model.","order":3,"origin":"template"},{"id":"c-3.7.A.4","parentId":"c-3.7.A","code":"3.7.A.4","text":"Sinusoidal function models can be constructed for a data set with technology by estimating key values or using sinusoidal regressions.","order":4,"origin":"template"},{"id":"c-3.7.A.5","parentId":"c-3.7.A","code":"3.7.A.5","text":"Sinusoidal functions that model a data set are frequently only useful over their contextual domain, can be used to predict values of the dependent variable from values of the independent variable, and may be used to determine values of the independent variable from values of the dependent variable.","order":5,"origin":"template"},{"id":"c-3.8.A","parentId":"c-3.8","code":"3.8.A","text":"Construct representations of the tangent function using the unit circle.","order":1,"origin":"template"},{"id":"c-3.8.A.1","parentId":"c-3.8.A","code":"3.8.A.1","text":"Given an angle of measure θ in standard position and a unit circle centered at the origin, there is a point, P, where the terminal ray intersects the circle. The tangent function, f(θ) = tan θ, gives the slope of the terminal ray.","order":1,"origin":"template"},{"id":"c-3.8.A.2","parentId":"c-3.8.A","code":"3.8.A.2","text":"Because the slope of the terminal ray is the ratio of the change in the y-values to the change in the x-values between any two points on the ray, the tangent function is also the ratio of the sine function to the cosine function. Therefore, sin θ tan θ =, where cos θ ≠ 0. cos θ","order":2,"origin":"template"},{"id":"c-3.8.B","parentId":"c-3.8","code":"3.8.B","text":"Describe key characteristics of the tangent function.","order":2,"origin":"template"},{"id":"c-3.8.B.1","parentId":"c-3.8.B","code":"3.8.B.1","text":"Because the slope values of the terminal ray repeat every one-half revolution of the circle, the tangent function has a period ofπ.","order":1,"origin":"template"},{"id":"c-3.8.B.2","parentId":"c-3.8.B","code":"3.8.B.2","text":"The tangent function demonstrates periodic asymptotic behavior at input values π θ = + kπ, for integer values of k, because cos θ = 0 at those values.","order":2,"origin":"template"},{"id":"c-3.8.B.3","parentId":"c-3.8.B","code":"3.8.B.3","text":"The tangent function increases and its graph changes from concave down to concave up between consecutive asymptotes.","order":3,"origin":"template"},{"id":"c-3.8.C","parentId":"c-3.8","code":"3.8.C","text":"Describe additive and multiplicative transformations involving the tangent function.","order":3,"origin":"template"},{"id":"c-3.8.C.1","parentId":"c-3.8.C","code":"3.8.C.1","text":"The graph of the additive transformation g(θ) = tan θ + d of the tangent function f(θ) = tan θ is a vertical translation of the graph of f and the line containing its points of inflection by d units.","order":1,"origin":"template"},{"id":"c-3.8.C.2","parentId":"c-3.8.C","code":"3.8.C.2","text":"The graph of the additive transformation g(θ) = tan(θ + c) of the tangent function f(θ) = tan θ is a horizontal translation, or phase shift, of the graph of f by −c units.","order":2,"origin":"template"},{"id":"c-3.8.C.3","parentId":"c-3.8.C","code":"3.8.C.3","text":"The graph of the multiplicative transformation g(θ) = a tan θ of the tangent function f(θ) = tan θ is a vertical dilation of the graph of f by a factor of |a|. If a < 0, the transformation involves a reflection over the x-axis.","order":3,"origin":"template"},{"id":"c-3.8.C.4","parentId":"c-3.8.C","code":"3.8.C.4","text":"The graph of the multiplicative transformation g(θ) = tan(bθ) of the tangent function f(θ) = tan θ is a horizontal dilation of the graph of f and differs in period by a factor of 1/|b|. If b < 0, the transformation involves a reflection over the y-axis.","order":4,"origin":"template"},{"id":"c-3.8.C.5","parentId":"c-3.8.C","code":"3.8.C.5","text":"The graph of y = f(θ) = a tan(b(θ + c)) + d is a vertical dilation of the graph of y = tan θ by a factor of |a|, has a period of π/|b| units, is a vertical shift of the line containing the points of inflection of the graph of y = tan θ by d units, and is a phase shift of −c units.","order":5,"origin":"template"},{"id":"c-3.9.A","parentId":"c-3.9","code":"3.9.A","text":"Construct analytical and graphical representations of the inverse of the sine, cosine, and tangent functions over a restricted domain.","order":1,"origin":"template"},{"id":"c-3.9.A.1","parentId":"c-3.9.A","code":"3.9.A.1","text":"For inverse trigonometric functions, the input and output values are switched from their corresponding trigonometric functions, so the output value of an inverse trigonometric function is often interpreted as an angle measure and the input is a value in the range of the corresponding trigonometric function.","order":1,"origin":"template"},{"id":"c-3.9.A.2","parentId":"c-3.9.A","code":"3.9.A.2","text":"The inverse trigonometric functions are called arcsine, arccosine, and arctangent (also represented as sin⁻¹ x, cos⁻¹ x, and tan⁻¹ x). Because the corresponding trigonometric functions are periodic, they are only invertible if they have restricted domains.","order":2,"origin":"template"},{"id":"c-3.9.A.3","parentId":"c-3.9.A","code":"3.9.A.3","text":"In order to define their respective inverse functions, the domain of the sine function is [ π π ] restricted to -,, the cosine function to |[ 2 2 |] π π ]0, π], and the tangent function to(-,).","order":3,"origin":"template"},{"id":"c-3.10.A","parentId":"c-3.10","code":"3.10.A","text":"Solve equations and inequalities involving trigonometric functions.","order":1,"origin":"template"},{"id":"c-3.10.A.1","parentId":"c-3.10.A","code":"3.10.A.1","text":"Inverse trigonometric functions are useful in solving equations and inequalities involving trigonometric functions, but solutions may need to be modified due to domain restrictions.","order":1,"origin":"template"},{"id":"c-3.10.A.2","parentId":"c-3.10.A","code":"3.10.A.2","text":"Because trigonometric functions are periodic, there are often infinitely many solutions to trigonometric equations.","order":2,"origin":"template"},{"id":"c-3.10.A.3","parentId":"c-3.10.A","code":"3.10.A.3","text":"In trigonometric equations and inequalities arising from a contextual scenario, there is often a domain restriction that can be implied from the context, which limits the number of solutions.","order":3,"origin":"template"},{"id":"c-3.11.A","parentId":"c-3.11","code":"3.11.A","text":"Identify key characteristics of functions that involve quotients of the sine and cosine functions.","order":1,"origin":"template"},{"id":"c-3.11.A.1","parentId":"c-3.11.A","code":"3.11.A.1","text":"The secant function, f(θ) = sec θ, is the reciprocal of the cosine function, where cos θ ≠ 0.","order":1,"origin":"template"},{"id":"c-3.11.A.2","parentId":"c-3.11.A","code":"3.11.A.2","text":"The cosecant function, f(θ) = csc θ, is the reciprocal of the sine function, where sin θ ≠ 0.","order":2,"origin":"template"},{"id":"c-3.11.A.3","parentId":"c-3.11.A","code":"3.11.A.3","text":"The graphs of the secant and cosecant functions have vertical asymptotes where cosine and sine are zero, respectively, and have a range of (−∞, −1] ∪ [1, ∞).","order":3,"origin":"template"},{"id":"c-3.11.A.4","parentId":"c-3.11.A","code":"3.11.A.4","text":"The cotangent function, f(θ) = cot θ, is the reciprocal of the tangent function, where tan θ ≠ 0. Equivalently, cot θ = cos θ / sin θ, where sin θ ≠ 0.","order":4,"origin":"template"},{"id":"c-3.11.A.5","parentId":"c-3.11.A","code":"3.11.A.5","text":"The graph of the cotangent function has vertical asymptotes for domain values where tan θ = 0 and is decreasing between consecutive asymptotes.","order":5,"origin":"template"},{"id":"c-3.12.A","parentId":"c-3.12","code":"3.12.A","text":"Rewrite trigonometric expressions in equivalent forms with the Pythagorean identity.","order":1,"origin":"template"},{"id":"c-3.12.A.1","parentId":"c-3.12.A","code":"3.12.A.1","text":"The Pythagorean Theorem can be applied to right triangles with points on the unit circle at coordinates (cos θ, sin θ), resulting in the Pythagorean identity: sin²θ + cos²θ = 1.","order":1,"origin":"template"},{"id":"c-3.12.A.2","parentId":"c-3.12.A","code":"3.12.A.2","text":"The Pythagorean identity can be algebraically manipulated into other forms involving trigonometric functions, such as tan²θ = sec²θ − 1, and can be used to establish other trigonometric relationships, such as arcsin x = arccos √(1 − x²), with appropriate domain restrictions.","order":2,"origin":"template"},{"id":"c-3.12.B","parentId":"c-3.12","code":"3.12.B","text":"Rewrite trigonometric expressions in equivalent forms with sine and cosine sum identities.","order":2,"origin":"template"},{"id":"c-3.12.B.1","parentId":"c-3.12.B","code":"3.12.B.1","text":"The sum identity for sine is sin(α + β) α os β=+siconαs cinsβ.","order":1,"origin":"template"},{"id":"c-3.12.B.2","parentId":"c-3.12.B","code":"3.12.B.2","text":"The sum identity for cosine is co (α + β) s α co β=csos αssiinn β.-","order":2,"origin":"template"},{"id":"c-3.12.B.3","parentId":"c-3.12.B","code":"3.12.B.3","text":"The sum identities for sine and cosine can also be used as difference and double-angle identities.","order":3,"origin":"template"},{"id":"c-3.12.B.4","parentId":"c-3.12.B","code":"3.12.B.4","text":"Properties of trigonometric functions, known trigonometric identities, and other algebraic properties can be used to verify additional trigonometric identities.","order":4,"origin":"template"},{"id":"c-3.12.C","parentId":"c-3.12","code":"3.12.C","text":"Solve equations using equivalent analytic representations of trigonometric functions.","order":3,"origin":"template"},{"id":"c-3.12.C.1","parentId":"c-3.12.C","code":"3.12.C.1","text":"A specific equivalent form involving trigonometric expressions can make information more accessible.","order":1,"origin":"template"},{"id":"c-3.12.C.2","parentId":"c-3.12.C","code":"3.12.C.2","text":"Equivalent trigonometric forms may be useful in solving trigonometric equations and inequalities.","order":2,"origin":"template"},{"id":"c-3.13.A","parentId":"c-3.13","code":"3.13.A","text":"Determine the location of a point in the plane using both rectangular and polar coordinates.","order":1,"origin":"template"},{"id":"c-3.13.A.1","parentId":"c-3.13.A","code":"3.13.A.1","text":"The polar coordinate system is based on a grid of circles centered at the origin and on lines through the origin. The positive x-axis is called the polar axis. Polar coordinates of a point are defined as an ordered pair, (r, θ). The value of θ is given by the measure of an angle in standard position whose terminal ray lies in a line that passes through the point, and r is the radial displacement of the point from the origin. Positive values of r indicate radial displacement from the origin along the terminal ray of the angle θ. Negative values of r indicate radial displacement from the origin along the line containing the terminal ray of the angle θ —but in the opposite direction of the terminal ray of the angle θ. In the polar coordinate system, the same point can be represented many ways with combinations of positive and negative values of r and θ.","order":1,"origin":"template"},{"id":"c-3.13.A.2","parentId":"c-3.13.A","code":"3.13.A.2","text":"The coordinates of a point in the polar coordinate system,(r, θ), can be converted to coordinates in the rectangular coordinate system,(x, y), using x = r cos θ and y = r sin θ.","order":2,"origin":"template"},{"id":"c-3.13.A.3","parentId":"c-3.13.A","code":"3.13.A.3","text":"The coordinates of a point in the rectangular coordinate system,(x, y), can be converted to coordinates in the polar coordinate system, 2 2 { y } (r, θ), using r x =+ y and θ = arctan| | { x } { y } for x > 0 or θ = arctan| | + π for x < 0. { x }","order":3,"origin":"template"},{"id":"c-3.13.A.4","parentId":"c-3.13.A","code":"3.13.A.4","text":"A complex number can be understood as a point in the complex plane and can be determined by its corresponding rectangular or polar coordinates. When the complex number has the rectangular coordinates (a, b), it can be expressed as a + bi. When the complex number has polar coordinates (r, θ), it can be expressed as(r co θ) + i(rs in θ). s","order":4,"origin":"template"},{"id":"c-3.14.A","parentId":"c-3.14","code":"3.14.A","text":"Construct graphs of polar functions.","order":1,"origin":"template"},{"id":"c-3.14.A.1","parentId":"c-3.14.A","code":"3.14.A.1","text":"The graph of the function r = f(θ) in polar coordinates consists of input-output pairs of values where the input values are angle measures and the output values are radii.","order":1,"origin":"template"},{"id":"c-3.14.A.2","parentId":"c-3.14.A","code":"3.14.A.2","text":"The domain of the polar function r = f(θ), given graphically, can be restricted to a desired portion of the function by selecting endpoints corresponding to the desired angle and radius.","order":2,"origin":"template"},{"id":"c-3.14.A.3","parentId":"c-3.14.A","code":"3.14.A.3","text":"When graphing polar functions in the form of r = f(θ), changes in input values relate to changes in angle measures from the polar axis, and changes in output values relate to changes in signed radial displacements from the origin.","order":3,"origin":"template"},{"id":"c-3.15.A","parentId":"c-3.15","code":"3.15.A","text":"Describe characteristics of the graph of a polar function.","order":1,"origin":"template"},{"id":"c-3.15.A.1","parentId":"c-3.15.A","code":"3.15.A.1","text":"If a polar function, r = f(θ), is positive and increasing or negative and decreasing, then the distance between the point with polar coordinates (f(θ), θ) and the origin is increasing.","order":1,"origin":"template"},{"id":"c-3.15.A.2","parentId":"c-3.15.A","code":"3.15.A.2","text":"If a polar function, r = f(θ), is positive and decreasing or negative and increasing, then the distance between the point with polar coordinates (f(θ), θ) and the origin is decreasing.","order":2,"origin":"template"},{"id":"c-3.15.A.3","parentId":"c-3.15.A","code":"3.15.A.3","text":"For a polar function, r = f(θ), if the function changes from increasing to decreasing or decreasing to increasing on an interval, then the function has a relative extremum on the interval corresponding to a point relatively closest to or farthest from the origin.","order":3,"origin":"template"},{"id":"c-3.15.A.4","parentId":"c-3.15.A","code":"3.15.A.4","text":"The average rate of change of r with respect to θ over an interval of θ is the ratio of the change in the signed radius values to the change in θ over an interval of θ. Graphically, the average rate of change indicates the rate at which the signed radius is changing per radian.","order":4,"origin":"template"},{"id":"c-3.15.A.5","parentId":"c-3.15.A","code":"3.15.A.5","text":"The average rate of change of r with respect to θ over an interval of θ can be used to estimate values of the function within the interval.","order":5,"origin":"template"},{"id":"c-4.1.A","parentId":"c-4.1","code":"4.1.A","text":"Construct a graph or table of values for a parametric function represented analytically.","order":1,"origin":"template"},{"id":"c-4.1.A.1","parentId":"c-4.1.A","code":"4.1.A.1","text":"A parametric function in ℝ², the set of all ordered pairs of two real numbers, consists of a set of two parametric equations in which two dependent variables, x and y, are dependent on a single independent variable, t, called the parameter.","order":1,"origin":"template"},{"id":"c-4.1.A.2","parentId":"c-4.1.A","code":"4.1.A.2","text":"Because variables x and y are dependent on the independent variable, t, the coordinates (x_i, y_i) at time t_i can be written as functions of t and can be expressed as the single parametric function f(t) = (x(t), y(t)), where in this case x and y are names of two functions.","order":2,"origin":"template"},{"id":"c-4.1.A.3","parentId":"c-4.1.A","code":"4.1.A.3","text":"A numerical table of values can be generated for the parametric function f(t) = (x(t), y(t)) by evaluating x_i and y_i at several values of t_i within the domain.","order":3,"origin":"template"},{"id":"c-4.1.A.4","parentId":"c-4.1.A","code":"4.1.A.4","text":"A graph of a parametric function can be sketched by connecting several points from the numerical table of values in order of increasing value of t.","order":4,"origin":"template"},{"id":"c-4.1.A.5","parentId":"c-4.1.A","code":"4.1.A.5","text":"The domain of the parametric function f is often restricted, which results in start and end points on the graph of f.","order":5,"origin":"template"},{"id":"c-4.2.A","parentId":"c-4.2","code":"4.2.A","text":"Identify key characteristics of a parametric planar motion function that are related to position.","order":1,"origin":"template"},{"id":"c-4.2.A.1","parentId":"c-4.2.A","code":"4.2.A.1","text":"A parametric function given by f(t) = (x(t), y(t)) can be used to model particle motion in the plane. The graph of this function indicates the position of a particle at time t.","order":1,"origin":"template"},{"id":"c-4.2.A.2","parentId":"c-4.2.A","code":"4.2.A.2","text":"The horizontal and vertical extrema of a particle’s motion can be determined by identifying the maximum and minimum values of the functions x(t) and y(t), respectively.","order":2,"origin":"template"},{"id":"c-4.2.A.3","parentId":"c-4.2.A","code":"4.2.A.3","text":"The real zeros of the function x(t) correspond to y-intercepts, and the real zeros of y(t) correspond to x-intercepts.","order":3,"origin":"template"},{"id":"c-4.3.A","parentId":"c-4.3","code":"4.3.A","text":"Identify key characteristics of a parametric planar motion function that are related to direction and rate of change.","order":1,"origin":"template"},{"id":"c-4.3.A.1","parentId":"c-4.3.A","code":"4.3.A.1","text":"As the parameter increases, the direction of planar motion of a particle can be analyzed in terms of x and y independently. If x(t) is increasing or decreasing, the direction of motion is to the right or left, respectively. If y(t) is increasing or decreasing, the direction of motion is up or down, respectively.","order":1,"origin":"template"},{"id":"c-4.3.A.2","parentId":"c-4.3.A","code":"4.3.A.2","text":"At any given point in the plane, the direction of planar motion may be different for different values of t.","order":2,"origin":"template"},{"id":"c-4.3.A.3","parentId":"c-4.3.A","code":"4.3.A.3","text":"The same curve in the plane can be parametrized in different ways and can be traversed in different directions with different parametric functions.","order":3,"origin":"template"},{"id":"c-4.3.A.4","parentId":"c-4.3.A","code":"4.3.A.4","text":"Over a given interval [t_1, t_2] within the domain, the average rate of change can be computed for x(t) and y(t) independently. The ratio of the average rate of change of y to the average rate of change of x gives the slope of the graph between the points on the curve corresponding to t_1 and t_2, so long as the average rate of change of x(t) ≠ 0.","order":4,"origin":"template"},{"id":"c-4.4.A","parentId":"c-4.4","code":"4.4.A","text":"Express motion around a circle or along a line segment parametrically.","order":1,"origin":"template"},{"id":"c-4.4.A.1","parentId":"c-4.4.A","code":"4.4.A.1","text":"A complete counterclockwise revolution around the unit circle that starts and ends at (1, 0) and is centered at the origin can be modeled by (x(t), y(t)) = (cos t, sin t), with domain 0 ≤ t ≤ 2π.","order":1,"origin":"template"},{"id":"c-4.4.A.2","parentId":"c-4.4.A","code":"4.4.A.2","text":"Transformations of the parametric function (x(t), y(t)) = (cos t, sin t) can model any circular path traversed in the plane.","order":2,"origin":"template"},{"id":"c-4.4.A.3","parentId":"c-4.4.A","code":"4.4.A.3","text":"A linear path along the line segment from the point (x_1, y_1) to the point (x_2, y_2) can be parametrized many ways, including using an initial position (x_1, y_1) and rates of change for x with respect to t and y with respect to t.","order":3,"origin":"template"},{"id":"c-4.5.A","parentId":"c-4.5","code":"4.5.A","text":"Construct a graph of an equation involving two variables.","order":1,"origin":"template"},{"id":"c-4.5.A.1","parentId":"c-4.5.A","code":"4.5.A.1","text":"An equation involving two variables can implicitly describe one or more functions.","order":1,"origin":"template"},{"id":"c-4.5.A.2","parentId":"c-4.5.A","code":"4.5.A.2","text":"An equation involving two variables can be graphed by finding solutions to the equation.","order":2,"origin":"template"},{"id":"c-4.5.A.3","parentId":"c-4.5.A","code":"4.5.A.3","text":"Solving for one of the variables in an equation involving two variables can define a function whose graph is part or all of the graph of the equation.","order":3,"origin":"template"},{"id":"c-4.5.B","parentId":"c-4.5","code":"4.5.B","text":"Determine how the two quantities related in an implicitly defined function vary together.","order":2,"origin":"template"},{"id":"c-4.5.B.1","parentId":"c-4.5.B","code":"4.5.B.1","text":"For ordered pairs on the graph of an implicitly defined function that are close together, if the ratio of the change in the two variables is positive, then the two variables simultaneously increase or both decrease; conversely, if the ratio is negative, then as one variable increases, the other decreases.","order":1,"origin":"template"},{"id":"c-4.5.B.2","parentId":"c-4.5.B","code":"4.5.B.2","text":"The rate of change of x with respect to y or of y with respect to x can be zero, indicating vertical or horizontal intervals, respectively.","order":2,"origin":"template"},{"id":"c-4.6.A","parentId":"c-4.6","code":"4.6.A","text":"Represent conic sections with horizontal or vertical symmetry analytically.","order":1,"origin":"template"},{"id":"c-4.6.A.1","parentId":"c-4.6.A","code":"4.6.A.1","text":"A parabola with vertex (h, k) can, if a ≠ 0, be represented analytically as x − h = a(y − k)² if it opens left or right, or as y − k = a(x − h)² if it opens up or down.","order":1,"origin":"template"},{"id":"c-4.6.A.2","parentId":"c-4.6.A","code":"4.6.A.2","text":"An ellipse centered at (h, k) with horizontal radius a and vertical radius b can be represented analytically as (x − h)²/a² + (y − k)²/b² = 1. A circle is a special case of an ellipse where a = b.","order":2,"origin":"template"},{"id":"c-4.6.A.3","parentId":"c-4.6.A","code":"4.6.A.3","text":"A hyperbola centered at (h, k) with vertical and horizonal lines of symmetry can be represented algebraically as (x − h)²/a² − (y − k)²/b² = 1 for a hyperbola opening left and right, or as (y − k)²/b² − (x − h)²/a² = 1 for a hyperbola opening up and down. The asymptotes are y − k = ±(b/a)(x − h).","order":3,"origin":"template"},{"id":"c-4.7.A","parentId":"c-4.7","code":"4.7.A","text":"Represent a curve in the plane parametrically.","order":1,"origin":"template"},{"id":"c-4.7.A.1","parentId":"c-4.7.A","code":"4.7.A.1","text":"A parametrization (x(t), y(t)) for an implicitly defined function will, when x(t) and y(t) are substituted for x and y, respectively, satisfy the corresponding equation for every value of t in the domain.","order":1,"origin":"template"},{"id":"c-4.7.A.2","parentId":"c-4.7.A","code":"4.7.A.2","text":"If f is a function of x, then y = f(x) can be parametrized as (x(t), y(t)) = (t, f(t)). If f is invertible, its inverse can be parametrized as (x(t), y(t)) = (f(t), t) for an appropriate interval of t.","order":2,"origin":"template"},{"id":"c-4.7.B","parentId":"c-4.7","code":"4.7.B","text":"Represent conic sections parametrically.","order":2,"origin":"template"},{"id":"c-4.7.B.1","parentId":"c-4.7.B","code":"4.7.B.1","text":"A parabola can be parametrized in the same way that any equation that can be solved for x or y can be parametrized. Equations that can be solved for x can be parametrized as (x(t), y(t)) = (f(t), t) by solving for x and replacing y with t. Equations that can be solved for y can be parametrized as (x(t), y(t)) = (t, f(t)) by solving for y and replacing x with t.","order":1,"origin":"template"},{"id":"c-4.7.B.2","parentId":"c-4.7.B","code":"4.7.B.2","text":"An ellipse can be parametrized using the trigonometric functions x(t) = +h a cosandt y(t) = +k b sinfort 0 ≤ t 2≤π.","order":2,"origin":"template"},{"id":"c-4.7.B.3","parentId":"c-4.7.B","code":"4.7.B.3","text":"A hyperbola can be parametrized using trigonometric functions. For a hyperbola that opens left and right, the functions are x(t) = +h a secandt y(t) = +k b tanfort 0 ≤ t 2≤π. For a hyperbola that opens up and down, the functions are x(t) = +h a tanandt y(t) = +k b secfort 0 ≤ t 2≤π.","order":3,"origin":"template"},{"id":"c-4.8.A","parentId":"c-4.8","code":"4.8.A","text":"Identify characteristics of a vector.","order":1,"origin":"template"},{"id":"c-4.8.A.1","parentId":"c-4.8.A","code":"4.8.A.1","text":"A vector is a directed line segment. When a vector is placed in the plane, the point at the beginning of the line segment is called the tail, and the point at the end of the line segment is called the head. The length of the line segment is the magnitude of the vector.","order":1,"origin":"template"},{"id":"c-4.8.A.2","parentId":"c-4.8.A","code":"4.8.A.2","text":"A vector P₁P₂ with two components can be plotted in the xy-plane from P₁ = (x_1, y_1) to P₂ = (x_2, y_2). The vector is identified by a and b, where a = x_2 − x_1 and b = y_2 − y_1. The vector can be expressed as ⟨a, b⟩. A zero vector ⟨0, 0⟩ is the trivial case when P₁ = P₂.","order":2,"origin":"template"},{"id":"c-4.8.A.3","parentId":"c-4.8.A","code":"4.8.A.3","text":"The direction of the vector is parallel to the line segment from the origin to the point with coordinates (a, b). The magnitude of the vector is the square root of the sum of the squares of the components.","order":3,"origin":"template"},{"id":"c-4.8.A.4","parentId":"c-4.8.A","code":"4.8.A.4","text":"For a vector represented geometrically in the plane, the components of the vector can be found using trigonometry.","order":4,"origin":"template"},{"id":"c-4.8.B","parentId":"c-4.8","code":"4.8.B","text":"Determine sums and products involving vectors.","order":2,"origin":"template"},{"id":"c-4.8.B.1","parentId":"c-4.8.B","code":"4.8.B.1","text":"The multiplication of a constant and a vector results in a new vector whose components are found by multiplying the constant by each of the components of the original vector. The new vector is parallel to the original vector.","order":1,"origin":"template"},{"id":"c-4.8.B.2","parentId":"c-4.8.B","code":"4.8.B.2","text":"The sum of two vectors in ℝ² is a new vector whose components are found by adding the corresponding components of the original vectors. The new vector can be represented graphically as a vector whose tail corresponds to the tail of the first vector and whose head corresponds to the head of the second vector when the second vector’s tail is located at the first vector’s head.","order":2,"origin":"template"},{"id":"c-4.8.B.3","parentId":"c-4.8.B","code":"4.8.B.3","text":"The dot product of two vectors is the sum of the products of their corresponding components. That is, ⟨a_1, b_1⟩ · ⟨a_2, b_2⟩ = a_1a_2 + b_1b_2.","order":3,"origin":"template"},{"id":"c-4.8.C","parentId":"c-4.8","code":"4.8.C","text":"Determine a unit vector for a given vector.","order":3,"origin":"template"},{"id":"c-4.8.C.1","parentId":"c-4.8.C","code":"4.8.C.1","text":"A unit vector is a vector of magnitude 1. A unit vector in the same direction as a given nonzero vector can be found by scalar multiplying the vector by the reciprocal of its magnitude.","order":1,"origin":"template"},{"id":"c-4.8.C.2","parentId":"c-4.8.C","code":"4.8.C.2","text":"The vector ⟨a, b⟩ can be expressed as ai + bj in ℝ², where i and j are unit vectors in the x and y directions, respectively. That is, i = ⟨1, 0⟩ and j = ⟨0, 1⟩.","order":2,"origin":"template"},{"id":"c-4.8.D","parentId":"c-4.8","code":"4.8.D","text":"Determine angle measures between vectors and magnitudes of vectors involved in vector addition.","order":4,"origin":"template"},{"id":"c-4.8.D.1","parentId":"c-4.8.D","code":"4.8.D.1","text":"The dot product is geometrically equivalent to the product of the magnitudes of the two vectors and the cosine of the angle between them. Therefore, if the dot product of two nonzero vectors is zero, then the vectors are perpendicular.","order":1,"origin":"template"},{"id":"c-4.8.D.2","parentId":"c-4.8.D","code":"4.8.D.2","text":"The Law of Sines and Law of Cosines can be used to determine side lengths and angle measures of triangles formed by vector addition.","order":2,"origin":"template"},{"id":"c-4.9.A","parentId":"c-4.9","code":"4.9.A","text":"Represent planar motion in terms of vector-valued functions.","order":1,"origin":"template"},{"id":"c-4.9.A.1","parentId":"c-4.9.A","code":"4.9.A.1","text":"The position of a particle moving in a plane that is given by the parametric function f(t) = (x(t), y(t)) may be expressed as a vector-valued function, p(t) = x(t)i + y(t)j or p(t) = ⟨x(t), y(t)⟩. The magnitude of the position vector at time t gives the distance of the particle from the origin.","order":1,"origin":"template"},{"id":"c-4.9.A.2","parentId":"c-4.9.A","code":"4.9.A.2","text":"The vector-valued function v(t) = ⟨x(t), y(t)⟩ can be used to express the velocity of a particle moving in a plane at different times, t. At time t, the sign of x(t) indicates if the particle is moving right or left, and the sign of y(t) indicates if the particle is moving up or down. The magnitude of the velocity vector at time t gives the speed of the particle.","order":2,"origin":"template"},{"id":"c-4.10.A","parentId":"c-4.10","code":"4.10.A","text":"Determine the product of two matrices.","order":1,"origin":"template"},{"id":"c-4.10.A.1","parentId":"c-4.10.A","code":"4.10.A.1","text":"An n × m matrix is an array consisting of n rows and m columns.","order":1,"origin":"template"},{"id":"c-4.10.A.2","parentId":"c-4.10.A","code":"4.10.A.2","text":"Two matrices can be multiplied if the number of columns in the first matrix equals the number of rows in the second matrix. The product of the matrices is a new matrix in which the component in the ith row and jth column is the dot product of the ith row of the first matrix and the jth column of the second matrix.","order":2,"origin":"template"},{"id":"c-4.11.A","parentId":"c-4.11","code":"4.11.A","text":"Determine the inverse of a 2 × 2 matrix.","order":1,"origin":"template"},{"id":"c-4.11.A.1","parentId":"c-4.11.A","code":"4.11.A.1","text":"The identity matrix, I, is a square matrix consisting of 1s on the diagonal from the top left to bottom right and 0s everywhere else.","order":1,"origin":"template"},{"id":"c-4.11.A.2","parentId":"c-4.11.A","code":"4.11.A.2","text":"Multiplying a square matrix by its corresponding identity matrix results in the original square matrix.","order":2,"origin":"template"},{"id":"c-4.11.A.3","parentId":"c-4.11.A","code":"4.11.A.3","text":"The product of a square matrix and its inverse, when it exists, is the identity matrix of the same size.","order":3,"origin":"template"},{"id":"c-4.11.A.4","parentId":"c-4.11.A","code":"4.11.A.4","text":"The inverse of a 2 × 2 matrix, when it exists, can be calculated with or without technology.","order":4,"origin":"template"},{"id":"c-4.11.B","parentId":"c-4.11","code":"4.11.B","text":"Apply the value of the determinant to invertibility and vectors.","order":2,"origin":"template"},{"id":"c-4.11.B.1","parentId":"c-4.11.B","code":"4.11.B.1","text":"The determinant of the matrix A = [[a, b], [c, d]] is ad − bc. The determinant can be calculated with or without technology and is denoted det(A).","order":1,"origin":"template"},{"id":"c-4.11.B.2","parentId":"c-4.11.B","code":"4.11.B.2","text":"If a 2 × 2 matrix consists of two column or row vectors from ℝ², then the nonzero absolute value of the determinant of the matrix is the area of the parallelogram spanned by the vectors represented in the columns or rows of the matrix. If the determinant equals 0, then the vectors are parallel.","order":2,"origin":"template"},{"id":"c-4.11.B.3","parentId":"c-4.11.B","code":"4.11.B.3","text":"The square matrix A has an inverse if and only if det(A) ≠ 0.","order":3,"origin":"template"},{"id":"c-4.12.A","parentId":"c-4.12","code":"4.12.A","text":"Determine the output vectors of a linear transformation using a 2 × 2 matrix.","order":1,"origin":"template"},{"id":"c-4.12.A.1","parentId":"c-4.12.A","code":"4.12.A.1","text":"A linear transformation is a function that maps an input vector to an output vector such that each component of the output vector is the sum of constant multiples of the input vector components.","order":1,"origin":"template"},{"id":"c-4.12.A.2","parentId":"c-4.12.A","code":"4.12.A.2","text":"A linear transformation will map the zero vector to the zero vector.","order":2,"origin":"template"},{"id":"c-4.12.A.3","parentId":"c-4.12.A","code":"4.12.A.3","text":"A single vector in ℝ² can be expressed as a 2 × 1 matrix. A set of n vectors in ℝ² can be expressed as a 2 × n matrix.","order":3,"origin":"template"},{"id":"c-4.12.A.4","parentId":"c-4.12.A","code":"4.12.A.4","text":"For a linear transformation, L, from ℝ² to ℝ², there is a unique 2 × 2 matrix, A, such that L(v) = Av for vectors in ℝ². Conversely, for a given 2 × 2 matrix, A, the function L(v) = Av is a linear transformation from ℝ² to ℝ².","order":4,"origin":"template"},{"id":"c-4.12.A.5","parentId":"c-4.12.A","code":"4.12.A.5","text":"Multiplication of a 2 × 2 transformation matrix, A, and a 2 × n matrix of n input vectors gives a 2 × n matrix of the n output vectors for the linear transformation L(v) = Av.","order":5,"origin":"template"},{"id":"c-4.13.A","parentId":"c-4.13","code":"4.13.A","text":"Determine the association between a linear transformation and a matrix.","order":1,"origin":"template"},{"id":"c-4.13.A.1","parentId":"c-4.13.A","code":"4.13.A.1","text":"The linear transformation mapping ⟨x, y⟩ to ⟨a_11 x + a_12 y, a_21 x + a_22 y⟩ is associated with the matrix [[a_11, a_12], [a_21, a_22]].","order":1,"origin":"template"},{"id":"c-4.13.A.2","parentId":"c-4.13.A","code":"4.13.A.2","text":"The mapping of the unit vectors in a linear transformation provides valuable information for determining the associated matrix.","order":2,"origin":"template"},{"id":"c-4.13.A.3","parentId":"c-4.13.A","code":"4.13.A.3","text":"The matrix [[cos θ, −sin θ], [sin θ, cos θ]] is associated with a linear transformation of vectors that rotates every vector an angle θ counterclockwise about the origin.","order":3,"origin":"template"},{"id":"c-4.13.A.4","parentId":"c-4.13.A","code":"4.13.A.4","text":"The absolute value of the determinant of a 2 × 2 transformation matrix gives the magnitude of the dilation of regions in ℝ² under the transformation.","order":4,"origin":"template"},{"id":"c-4.13.B","parentId":"c-4.13","code":"4.13.B","text":"Determine the composition of two linear transformations.","order":2,"origin":"template"},{"id":"c-4.13.B.1","parentId":"c-4.13.B","code":"4.13.B.1","text":"The composition of two linear transformations is a linear transformation.","order":1,"origin":"template"},{"id":"c-4.13.B.2","parentId":"c-4.13.B","code":"4.13.B.2","text":"The matrix associated with the composition of two linear transformations is the product of the matrices associated with each linear transformation.","order":2,"origin":"template"},{"id":"c-4.13.C","parentId":"c-4.13","code":"4.13.C","text":"Determine the inverse of a linear transformation.","order":3,"origin":"template"},{"id":"c-4.13.C.1","parentId":"c-4.13.C","code":"4.13.C.1","text":"Two linear transformations are inverses if their composition maps any vector to itself.","order":1,"origin":"template"},{"id":"c-4.13.C.2","parentId":"c-4.13.C","code":"4.13.C.2","text":"If a linear transformation, L, is given by L(v) = Av, then its inverse transformation is given by L⁻¹(v) = A⁻¹v, where A⁻¹ is the inverse of the matrix A.","order":2,"origin":"template"},{"id":"c-4.14.A","parentId":"c-4.14","code":"4.14.A","text":"Construct a model of a scenario involving transitions between two states using matrices.","order":1,"origin":"template"},{"id":"c-4.14.A.1","parentId":"c-4.14.A","code":"4.14.A.1","text":"A contextual scenario can indicate the rate of transitions between states as percent changes. A matrix can be constructed based on these rates to model how states change over discrete intervals.","order":1,"origin":"template"},{"id":"c-4.14.B","parentId":"c-4.14","code":"4.14.B","text":"Apply matrix models to predict future and past states for n transition steps.","order":2,"origin":"template"},{"id":"c-4.14.B.1","parentId":"c-4.14.B","code":"4.14.B.1","text":"The product of a matrix that models transitions between states and a corresponding state vector can predict future states.","order":1,"origin":"template"},{"id":"c-4.14.B.2","parentId":"c-4.14.B","code":"4.14.B.2","text":"Repeated multiplication of a matrix that models the transitions between states and corresponding resultant state vectors can predict the steady state, a distribution between states that does not change from one step to the next.","order":2,"origin":"template"},{"id":"c-4.14.B.3","parentId":"c-4.14.B","code":"4.14.B.3","text":"The product of the inverse of a matrix that models transitions between states and a corresponding state vector can predict past states.","order":3,"origin":"template"}]},{"id":"practices","name":"AP Precalculus mathematical practices","levels":["Practice","Skill"],"nodes":[{"id":"p-1","parentId":null,"code":"1","text":"Procedural and Symbolic Fluency","order":1,"origin":"template","meta":{"description":"Algebraically manipulate functions, equations, and expressions."}},{"id":"p-2","parentId":null,"code":"2","text":"Multiple Representations","order":2,"origin":"template","meta":{"description":"Translate mathematical information between representations."}},{"id":"p-3","parentId":null,"code":"3","text":"Communication and Reasoning","order":3,"origin":"template","meta":{"description":"Communicate with precise language, and provide rationales for conclusions."}},{"id":"p-1.A","parentId":"p-1","code":"1.A","text":"Solve equations and inequalities represented analytically, with and without technology.","order":1,"origin":"template"},{"id":"p-1.B","parentId":"p-1","code":"1.B","text":"Express functions, equations, or expressions in analytically equivalent forms that are useful in a given mathematical or applied context.","order":2,"origin":"template"},{"id":"p-1.C","parentId":"p-1","code":"1.C","text":"Construct new functions, using transformations, compositions, inverses, or regressions, that may be useful in modeling contexts, criteria, or data, with and without technology.","order":3,"origin":"template"},{"id":"p-2.A","parentId":"p-2","code":"2.A","text":"Identify information from graphical, numerical, analytical, and verbal representations to answer a question or construct a model, with and without technology.","order":1,"origin":"template"},{"id":"p-2.B","parentId":"p-2","code":"2.B","text":"Construct equivalent graphical, numerical, analytical, and verbal representations of functions that are useful in a given mathematical or applied context, with and without technology.","order":2,"origin":"template"},{"id":"p-3.A","parentId":"p-3","code":"3.A","text":"Describe the characteristics of a function with varying levels of precision, depending on the function representation and available mathematical tools.","order":1,"origin":"template"},{"id":"p-3.B","parentId":"p-3","code":"3.B","text":"Apply numerical results in a given mathematical or applied context.","order":2,"origin":"template"},{"id":"p-3.C","parentId":"p-3","code":"3.C","text":"Support conclusions or choices with a logical rationale or appropriate data.","order":3,"origin":"template"}]}],"suggestedSkills":{"c-1.1":["p-2.B","p-3.A"],"c-1.2":["p-2.A","p-3.A"],"c-1.3":["p-3.B","p-3.C"],"c-1.4":["p-2.A","p-3.A"],"c-1.5":["p-1.B","p-2.B"],"c-1.6":["p-3.A"],"c-1.7":["p-1.B","p-3.A"],"c-1.8":["p-1.A"],"c-1.9":["p-2.A"],"c-1.10":["p-3.C"],"c-1.11":["p-1.B","p-3.B"],"c-1.12":["p-1.C","p-3.A"],"c-1.13":["p-2.A","p-3.C"],"c-1.14":["p-1.C","p-3.B"],"c-2.1":["p-1.B","p-3.A"],"c-2.2":["p-1.C","p-3.B"],"c-2.3":["p-3.A"],"c-2.4":["p-1.B","p-3.A"],"c-2.5":["p-1.C","p-3.B"],"c-2.6":["p-2.A","p-3.C"],"c-2.7":["p-1.C","p-2.B"],"c-2.8":["p-1.A","p-2.B"],"c-2.9":["p-1.B"],"c-2.10":["p-1.C","p-2.B"],"c-2.11":["p-3.A"],"c-2.12":["p-1.B","p-3.A"],"c-2.13":["p-1.A","p-1.B","p-1.C"],"c-2.14":["p-1.C","p-3.B"],"c-2.15":["p-2.B","p-3.C"],"c-3.1":["p-2.B","p-3.A"],"c-3.2":["p-2.A","p-3.A"],"c-3.3":["p-2.A","p-3.B"],"c-3.4":["p-2.A","p-3.A"],"c-3.5":["p-2.A","p-3.A"],"c-3.6":["p-1.C","p-2.B"],"c-3.7":["p-1.C","p-3.C"],"c-3.8":["p-2.A","p-3.A"],"c-3.9":["p-1.C","p-2.B"],"c-3.10":["p-1.A","p-2.A","p-3.B"],"c-3.11":["p-2.B","p-3.A"],"c-3.12":["p-1.A","p-1.B","p-3.B"],"c-3.13":["p-1.B","p-2.A"],"c-3.14":["p-2.B","p-3.A"],"c-3.15":["p-3.A","p-3.C"],"c-4.1":["p-1.A","p-2.B"],"c-4.2":["p-3.A","p-3.B"],"c-4.3":["p-3.B","p-3.C"],"c-4.4":["p-1.B","p-1.C"],"c-4.5":["p-2.B","p-3.A"],"c-4.6":["p-1.B","p-2.A","p-2.B"],"c-4.7":["p-1.B","p-2.A"],"c-4.8":["p-2.A","p-3.A","p-3.B"],"c-4.9":["p-3.C"],"c-4.10":["p-1.B","p-3.B"],"c-4.11":["p-1.B","p-3.B"],"c-4.12":["p-1.B"],"c-4.13":["p-1.B","p-2.A","p-3.A"],"c-4.14":["p-1.C","p-3.B","p-3.C"]},"activityBank":[]}};
